  'Privacy reminders\n• No names, ID numbers or exact ages.\n• Cover names / file numbers on any photo before capturing.\n• Be careful with exact dates and rare details that could identify a patient.\n• This is a personal learning log, not the official medical record.\n• Ask your hospital about its documentation and photo policy.\n• Keep backups somewhere private. A forgotten backup password cannot be recovered.\n• Voice typing on the keyboard may send audio to the internet: do not dictate patient details.': 'تنبيهات الخصوصية\n• بدون أسماء أو أرقام هوية أو أعمار دقيقة.\n• غطِّ الأسماء وأرقام الملفات على أي صورة قبل التقاطها.\n• احذر من التواريخ الدقيقة والتفاصيل النادرة التي قد تدل على مريض.\n• هذا سجل تعلّم شخصي وليس السجل الطبي الرسمي.\n• اسأل مستشفاك عن سياسة التوثيق والتصوير.\n• احفظ النسخ الاحتياطية في مكان خاص. كلمة سر النسخة إذا ضاعت لا يمكن استرجاعها.\n• الإملاء الصوتي في لوحة المفاتيح قد يرسل الصوت إلى الإنترنت: لا تُملِ تفاصيل المرضى.',
