  'This code is not valid for this phone. Check that you pasted the whole code you received for the request made on THIS phone.': 'هذا الرمز غير صالح لهذا الهاتف. تأكد من لصق الرمز كاملًا وأنه صادر للطلب المقدَّم من هذا الهاتف.',
