  'Optional. Your own key, stored only on this phone.': 'اختياري. مفتاحك الخاص، ويُحفظ على هذا الهاتف فقط.',
  'How your data is handled': 'كيف تُعالَج بياناتك',
  'The app works fully without AI and without internet. AI is optional and only makes suggestions: nothing is saved without your confirmation.': 'يعمل التطبيق بالكامل بدون ذكاء اصطناعي وبدون إنترنت. الذكاء الاصطناعي اختياري ويقدّم اقتراحات فقط: لا يُحفظ أي شيء دون موافقتك.',
  'You use your own key. It is stored only on this phone (Android Keystore) and is never part of backups or exports. It is sent only to the provider you choose.': 'تستخدم مفتاحك الخاص. يُحفظ على هذا الهاتف فقط (Android Keystore) ولا يدخل في النسخ الاحتياطية أو التصدير. ويُرسل فقط إلى المزوّد الذي تختاره.',
  'Never sent: names, ids, phone numbers, addresses, hospital or doctor names, images, exact dates or whole notes. Case summaries are shown to you first.': 'لا يُرسل أبدًا: الأسماء، أرقام الهوية، أرقام الهاتف، العناوين، أسماء المستشفيات أو الأطباء، الصور، التواريخ الدقيقة أو الملاحظات الكاملة. تُعرض عليك ملخصات الحالات أولًا.',
  'AI answers can be wrong. Always check them against a reliable source.': 'قد تكون إجابات الذكاء الاصطناعي خاطئة. تحقّق منها دائمًا من مصدر موثوق.',
