  'Send': 'إرسال',
  'Allow case summaries?': 'السماح بملخصات الحالات؟',
  'For case help, a short de-identified summary (age band, sex, findings, labs in words) can be sent to your AI provider. Names, ids, phone numbers, addresses, hospital or doctor names, images and exact dates are never sent. You see and approve every summary first, and you can switch this off any time in AI settings.': 'للمساعدة في الحالة، يمكن إرسال ملخص قصير مجهول الهوية (فئة العمر، الجنس، الموجودات، التحاليل بالكلمات) إلى مزوّد الذكاء الاصطناعي. لا تُرسل أبدًا الأسماء ولا أرقام الهوية ولا أرقام الهاتف ولا العناوين ولا أسماء المستشفيات أو الأطباء ولا الصور ولا التواريخ الدقيقة. ترى كل ملخص وتوافق عليه أولًا، ويمكنك إيقاف ذلك في أي وقت من إعدادات الذكاء الاصطناعي.',
  'Not now': 'ليس الآن',
  'Allow': 'سماح',
  'The key was not accepted. Check that it is copied completely and belongs to this provider.': 'لم يُقبل المفتاح. تأكد من نسخه كاملًا ومن أنه يخص هذا المزوّد.',
  'The free quota for today is used up. Try again later, or use another key or provider.': 'انتهت الحصة المجانية لهذا اليوم. حاول لاحقًا أو استخدم مفتاحًا أو مزوّدًا آخر.',
