  'No connection to the AI service.': 'لا يوجد اتصال بخدمة الذكاء الاصطناعي.',
  'The AI service took too long to answer. Try again.': 'استغرقت خدمة الذكاء الاصطناعي وقتًا طويلًا في الرد. حاول مجددًا.',
  'The AI service is busy right now. Try again in a moment.': 'خدمة الذكاء الاصطناعي مشغولة الآن. حاول بعد قليل.',
  'The AI service declined to answer this request.': 'رفضت خدمة الذكاء الاصطناعي الإجابة عن هذا الطلب.',
