  'AI is off: answers come from a local search of your library. You can turn AI on in Settings.': 'الذكاء الاصطناعي متوقف: تأتي الإجابات من بحث محلي في مكتبتك. يمكنك تشغيله من الإعدادات.',
  'You are offline: showing passages from your library. AI answers need internet.': 'لا يوجد اتصال: نعرض مقاطع من مكتبتك. إجابات الذكاء الاصطناعي تحتاج إلى الإنترنت.',
  'Answers use only passages from your installed library and name their sources. Check them in the article.': 'تستخدم الإجابات مقاطع من مكتبتك المثبتة فقط وتذكر مصادرها. تحقق منها في المقالة.',
  'No courses are downloaded yet. Install a course in Courses and library first.': 'لم يتم تنزيل أي مقرر بعد. ثبّت مقررًا من «المقررات والمكتبة» أولًا.',
