  'AI is off/offline: practising from your saved questions': 'الذكاء الاصطناعي متوقف أو لا يوجد اتصال: التدريب من أسئلتك المحفوظة',
  'Questions are written by AI from library passages and checked by the app. They may still contain mistakes: every question shows its source sentence. AI never changes your records.': 'يكتب الذكاء الاصطناعي الأسئلة من مقاطع المكتبة ويفحصها التطبيق. قد تبقى فيها أخطاء، لذلك يعرض كل سؤال الجملة المصدر. لا يغيّر الذكاء الاصطناعي سجلاتك أبدا.',
