  'Generate more when online': 'ولّد المزيد عند الاتصال بالإنترنت',
  'Turn AI on in Settings to generate new questions.': 'فعّل الذكاء الاصطناعي من الإعدادات لتوليد أسئلة جديدة.',
  'Options': 'خيارات',
  'Check each new question with a second AI pass': 'افحص كل سؤال جديد بمرحلة ذكاء اصطناعي ثانية',
  'Uses more requests; rejects questions where the check disagrees.': 'يستهلك طلبات أكثر؛ ويرفض الأسئلة التي لا يوافق عليها الفحص.',
  'Top up the bank when low': 'أضف أسئلة للبنك تلقائيا عند انخفاضه',
