  'Tap the + button and choose Quick case. Fill only the complaint and diagnosis, and finish the details later. Long-press the + button to open Quick case directly.': 'اضغط زر + ثم اختر حالة سريعة. املأ الشكوى والتشخيص فقط وأكمل التفاصيل لاحقاً. اضغط مطولاً على زر + لفتح الحالة السريعة مباشرة.',
  'How do I write a full case?': 'كيف أكتب حالة كاملة؟',
  'Tap + then Full case. The case has tabs: Info, History, Exam, Investigations, Assessment, Management, Progress, Learning and Timeline. A green dot on a tab means it has content. Everything saves automatically.': 'اضغط + ثم حالة كاملة. تحتوي الحالة على تبويبات: المعلومات، القصة، الفحص، الفحوصات، التقييم، العلاج، التطور، التعلم والجدول الزمني. النقطة الخضراء تعني أن التبويب يحتوي بيانات. كل شيء يُحفظ تلقائياً.',
  'Do I need to press Save?': 'هل أحتاج إلى الضغط على حفظ؟',
  'No. The case saves automatically a moment after you type. The top bar shows Saved or Saving. Use the Undo arrow to go back a step.': 'لا. تُحفظ الحالة تلقائياً بعد لحظات من الكتابة. يعرض الشريط العلوي حالة الحفظ. استخدم سهم التراجع للرجوع خطوة.',
  'What does Quick fill from template do?': 'ماذا يفعل الملء السريع من القالب؟',
  'In the case menu, Quick fill from specialty template adds a structured history and exam outline for the chosen specialty. Fill everything normal fills only empty fields and marks them as auto-filled so you confirm them. Vital signs and results are never filled.': 'من قائمة الحالة، يضيف الملء السريع من قالب التخصص هيكلاً للقصة والفحص حسب التخصص. أما ملء كل شيء كطبيعي فيملأ الحقول الفارغة فقط ويضع عليها علامة لتؤكدها. العلامات الحيوية والنتائج لا تُملأ أبداً.',
  'How do I edit or delete a case?': 'كيف أعدل حالة أو أحذفها؟',
  'Open the case from the Cases tab and edit any field. To delete, open the case menu (three dots) and choose Delete case.': 'افتح الحالة من تبويب الحالات وعدّل أي حقل. للحذف افتح قائمة الحالة (ثلاث نقاط) واختر حذف الحالة.',
  'How do I search my cases?': 'كيف أبحث في حالاتي؟',
  'Use the search box in the Cases tab. You can type plain words or use filters such as #tag, dx:pneumonia, spec:, setting:, is:starred, has:image. Use a minus sign to exclude a word.': 'استخدم مربع البحث في تبويب الحالات. اكتب كلمات عادية أو مرشحات مثل #وسم و dx:pneumonia و spec: و is:starred. استخدم علامة الناقص لاستثناء كلمة.',
  'How do I use tags and stars?': 'كيف أستخدم الوسوم والنجوم؟',
  'In the Info tab of a case add tags, star the case, or mark it To review later. Then filter by them from the Cases tab.': 'في تبويب المعلومات أضف وسوماً أو ضع نجمة أو علّم الحالة للمراجعة لاحقاً. ثم صفّها من تبويب الحالات.',
  'How do I add a photo to a case?': 'كيف أضيف صورة إلى حالة؟',
  'In the Investigations tab add an image from the camera or gallery. Cover any name before taking the photo. You can annotate, crop and hide areas inside the app. Photos are stored privately inside the app, not in your gallery.': 'في تبويب الفحوصات أضف صورة من الكاميرا أو المعرض. غطِّ أي اسم قبل التصوير. يمكنك التعليق والقص وإخفاء مناطق داخل التطبيق. تُحفظ الصور بشكل خاص داخل التطبيق وليس في المعرض.',
  'How do I log a procedure?': 'كيف أسجل إجراءً؟',
  'Tap + and choose Procedure. Pick the procedure, your role (observed, assisted, performed under supervision, performed independently) and your confidence. Counts feed your goals.': 'اضغط + واختر إجراء. اختر الإجراء ودورك (شاهدت، ساعدت، أجريت بإشراف، أجريت باستقلالية) وثقتك. تُحتسب الأعداد ضمن أهدافك.',
  'What are notes, questions, pearls and tasks?': 'ما هي الملاحظات والأسئلة والدرر والمهام؟',
  'The + menu also adds a Note, a clinical Question for later, a Pearl (one thing learned today, with a streak) and a Task with a due date.': 'تضيف قائمة + أيضاً ملاحظة وسؤالاً سريرياً للمراجعة لاحقاً ودرة (أهم شيء تعلمته اليوم مع تتابع الأيام) ومهمة بموعد.',
  'How do I set up a rotation?': 'كيف أنشئ دورة تدريبية؟',
  'Open Portfolio, then Rotations, and add a rotation with its name, hospital or department and start and end dates. New cases can then be linked to it, and you can export the rotation as PDF.': 'افتح الملف ثم الدورات وأضف دورة باسمها والمستشفى أو القسم وتاريخي البداية والنهاية. يمكن بعدها ربط الحالات الجديدة بها وتصدير الدورة بصيغة PDF.',
  'How do I set goals and targets?': 'كيف أضع الأهداف؟',
  'In a rotation, add Targets: number of cases, a procedure with performed and assisted counts, notes, reflections or signed entries. Progress bars update as you log.': 'في الدورة أضف أهدافاً: عدد الحالات أو إجراء بعدد المؤدى والمساعد أو ملاحظات أو تأملات أو مدخلات موقعة. تتحدث أشرطة التقدم أثناء التسجيل.',
  'How does supervisor sign-off work?': 'كيف يعمل توقيع المشرف؟',
  'On a case or procedure, add the supervisor name, role, level of supervision and date, then mark it signed after they sign on paper or verbally. No signature image is stored. Signed entries show in exports.': 'في الحالة أو الإجراء أضف اسم المشرف ودوره ومستوى الإشراف والتاريخ، ثم علّمه موقعاً بعد أن يوقع ورقياً أو شفهياً. لا تُخزن صورة توقيع. تظهر المدخلات الموقعة في التصدير.',
  'How do I use the library?': 'كيف أستخدم المكتبة؟',
  'The Library tab holds medical articles that work offline. Search by title, or turn on search inside articles. Open an article to read, highlight, favourite it or save it to your reading list.': 'تضم المكتبة مقالات طبية تعمل دون إنترنت. ابحث بالعنوان أو فعّل البحث داخل المقالات. افتح مقالاً لتقرأه وتضعه في المفضلة أو قائمة القراءة.',
  'How do I download library packs?': 'كيف أنزل حزم المكتبة؟',
  'In the Library tab open Manage courses, pick a pack and download it (Wi-Fi is recommended). Downloaded packs work offline. You can also import your own text files, and remove packs to free space.': 'في تبويب المكتبة افتح إدارة الدورات واختر حزمة ونزّلها (يُفضل Wi-Fi). تعمل الحزم المنزلة دون إنترنت. يمكنك أيضاً استيراد ملفات نصية خاصة بك وحذف الحزم لتوفير المساحة.',
  'Can I make notes and cards from articles?': 'هل يمكنني عمل ملاحظات وبطاقات من المقالات؟',
  'Yes. In an article add your own note, and make review cards from key points. Cards join the spaced review.': 'نعم. في المقال أضف ملاحظتك الخاصة وأنشئ بطاقات مراجعة من النقاط المهمة. تنضم البطاقات إلى المراجعة المتباعدة.',
  'How do the quizzes work?': 'كيف تعمل الاختبارات؟',
  'In the Learn tab pick Quiz and a course or topic. Wrong answers become your weak spots and can become review cards automatically.': 'في تبويب التعلم اختر الاختبار ثم دورة أو موضوعاً. تتحول الإجابات الخاطئة إلى نقاط ضعفك ويمكن أن تصبح بطاقات مراجعة تلقائياً.',
  'What are weak spots?': 'ما هي نقاط الضعف؟',
  'Topics you missed recently in quizzes. They are listed first in the study planner and in practice sessions.': 'مواضيع أخطأت فيها مؤخراً في الاختبارات. تظهر أولاً في مخطط الدراسة وفي جلسات التدريب.',
  'How does the study planner work?': 'كيف يعمل مخطط الدراسة؟',
  'Choose your exam date and the courses you are revising. The planner spreads topics over the days, puts your weak spots first and weights your current rotation.': 'اختر تاريخ الامتحان والدورات التي تراجعها. يوزع المخطط المواضيع على الأيام ويضع نقاط ضعفك أولاً ويعطي وزناً لدورتك الحالية.',
  'How does spaced review work?': 'كيف تعمل المراجعة المتباعدة؟',
  'Review cards come back on a schedule: cards you know return later, cards you miss return sooner. Open Review from Learn each day for a short session.': 'تعود البطاقات حسب جدول: ما تعرفه يعود لاحقاً وما تخطئ فيه يعود أسرع. افتح المراجعة من التعلم كل يوم لجلسة قصيرة.',
  'What is Replay this case?': 'ما هو إعادة عرض الحالة؟',
  'It hides your answer and asks you to reason through your own case again, then compares with what you recorded. Good for practising clinical reasoning.': 'يخفي إجابتك ويطلب منك إعادة التفكير في حالتك ثم يقارن مع ما سجلته. مفيد لتدريب التفكير السريري.',
  'How do I practise presenting a case?': 'كيف أتدرب على عرض حالة؟',
  'In the case menu choose Practice presenting, or Share case presentation to send a short summary with the case code and no names.': 'من قائمة الحالة اختر التدرب على العرض، أو مشاركة عرض الحالة لإرسال ملخص قصير بالرمز دون أسماء.',
  'Where are the calculators?': 'أين الحاسبات؟',
  'In Learn, open Calculators for clinical scores and dose helpers. They work offline. Always check results against your local protocol.': 'في التعلم افتح الحاسبات للمقاييس السريرية ومساعدات الجرعات. تعمل دون إنترنت. تحقق دائماً من النتائج وفق بروتوكولك المحلي.',
  'How do I set reminders?': 'كيف أضبط التذكيرات؟',
  'In Settings, Reminders: daily review, finishing draft cases and weekly goals. Allow notifications when Android asks. Reminders are local and need no internet.': 'في الإعدادات، التذكيرات: المراجعة اليومية وإنهاء المسودات والأهداف الأسبوعية. اسمح بالإشعارات عندما يطلب أندرويد. التذكيرات محلية ولا تحتاج إنترنت.',
  'What is a draft case?': 'ما هي الحالة المسودة؟',
  'A case with status Draft. A quick case stays a draft until you finish it. Home reminds you to continue the case you left.': 'حالة بوضع مسودة. تبقى الحالة السريعة مسودة حتى تكملها. تذكرك الرئيسية بمتابعة الحالة التي تركتها.',
  'How do I lock the app with a PIN?': 'كيف أقفل التطبيق برقم سري؟',
  'In Settings, Privacy & security, set a PIN of 4 to 6 digits and choose when to lock. You can also hide the app in recent apps and block screenshots. If you forget the PIN you may lose access, so keep a backup.': 'في الإعدادات، الخصوصية والأمان، اضبط رقماً من 4 إلى 6 أرقام واختر وقت القفل. يمكنك أيضاً إخفاء التطبيق في التطبيقات الأخيرة ومنع لقطات الشاشة. إن نسيت الرقم فقد تفقد الوصول لذا احتفظ بنسخة احتياطية.',
  'How do I keep patient data private?': 'كيف أحمي خصوصية المرضى؟',
  'Never type names, ID numbers or phone numbers. Use only the case code. Run Privacy check from the case menu: it flags numbers, phones and emails. Data stays on your phone.': 'لا تكتب أسماء أو أرقام هوية أو هواتف. استخدم رمز الحالة فقط. شغّل فحص الخصوصية من قائمة الحالة فهو ينبه إلى الأرقام والهواتف والبريد. تبقى البيانات على هاتفك.',
  'Can I store patient initials?': 'هل يمكنني حفظ الأحرف الأولى للمريض؟',
  'Only if you turn on Store patient initials in Settings. They stay on this phone and are never included in shared text, packs or AI requests.': 'فقط إذا فعّلت حفظ الأحرف الأولى في الإعدادات. تبقى على هذا الهاتف ولا تُضمَّن أبداً في النص المشارك أو الحزم أو طلبات الذكاء الاصطناعي.',
  'How do I back up my data?': 'كيف أنسخ بياناتي احتياطياً؟',
  'In Settings, Backup & export, choose Export encrypted backup, set a password and save the file somewhere safe (Drive, email to yourself). Restore it with Import backup. If you forget the password nobody can open it.': 'في الإعدادات، النسخ والتصدير، اختر تصدير نسخة مشفرة واضبط كلمة مرور واحفظ الملف في مكان آمن (درايف أو بريدك). استعدها بالاستيراد. إن نسيت كلمة المرور فلا أحد يستطيع فتحها.',
  'How do I move to a new phone?': 'كيف أنتقل إلى هاتف جديد؟',
  'Export an encrypted backup on the old phone, install MedLog on the new one and use Import backup. Library packs are downloaded again or imported.': 'صدّر نسخة مشفرة من الهاتف القديم وثبّت التطبيق على الجديد ثم استخدم الاستيراد. تُنزَّل حزم المكتبة من جديد.',
  'What is Data health?': 'ما هو فحص سلامة البيانات؟',
  'Settings, Data health checks every file can be read and recovers from the last good copy. Damaged files are kept in a corrupt folder, never deleted.': 'يفحص فحص سلامة البيانات في الإعدادات إمكانية قراءة كل ملف ويستعيد آخر نسخة سليمة. تُحفظ الملفات التالفة في مجلد خاص ولا تُحذف.',
  'How do I export a PDF?': 'كيف أصدّر ملف PDF؟',
  'In Settings or Portfolio choose Export logbook, pick the range or rotation and PDF or CSV. A single case has Export as PDF in its menu. You can add supervisor sign-off lines.': 'في الإعدادات أو الملف اختر تصدير السجل ثم المدى أو الدورة وPDF أو CSV. للحالة الواحدة خيار تصدير PDF في قائمتها. يمكنك إضافة خطوط توقيع المشرف.',
  'How do I share a case?': 'كيف أشارك حالة؟',
  'Case menu: Share as text (no initials), Share case presentation, or Share to colleague (encrypted) which makes a pack your colleague imports. Always run the privacy check first.': 'من قائمة الحالة: مشاركة كنص (دون أحرف أولى) أو مشاركة عرض الحالة أو المشاركة مع زميل (مشفرة) لإنشاء حزمة يستوردها زميلك. شغّل فحص الخصوصية أولاً.',
  'How do I import shared cases?': 'كيف أستورد حالات مشاركة؟',
  'Settings, Import backup or shared cases: choose the file and enter its password. You see a summary of new and updated cases before they are added.': 'الإعدادات، استيراد نسخة أو حالات مشاركة: اختر الملف وأدخل كلمة مروره. ترى ملخصاً بالحالات الجديدة والمحدثة قبل إضافتها.',
  'How do I change the language?': 'كيف أغير اللغة؟',
  'Settings, Language: English, Arabic or follow the phone. Your own typed text and stored values stay as you wrote them.': 'الإعدادات، اللغة: الإنجليزية أو العربية أو حسب الهاتف. تبقى نصوصك المكتوبة والقيم المخزنة كما كتبتها.',
  'What is the Medical terms language setting?': 'ما هو إعداد لغة المصطلحات الطبية؟',
  'In the Arabic app, medical terms stay in English by default because that is how they are written in charts. Change Medical terms language in Settings to show Arabic terms instead.': 'في التطبيق العربي تبقى المصطلحات الطبية بالإنجليزية افتراضياً لأنها تُكتب هكذا في الملفات. غيّر لغة المصطلحات الطبية في الإعدادات لعرض المصطلحات بالعربية.',
  'How do I change the look, dark mode or text size?': 'كيف أغير المظهر أو الوضع الداكن أو حجم الخط؟',
  'Settings, Appearance: light, dark or pure black mode, colour palette, text size, fonts and animations.': 'الإعدادات، المظهر: الوضع الفاتح أو الداكن أو الأسود، الألوان، حجم الخط، الخطوط والحركات.',
  'How do I use the calendar and duty days?': 'كيف أستخدم التقويم وأيام الدوام؟',
  'Open the Calendar to see shifts and logged items by day. In a rotation, generate duty days by weekdays and edit single days.': 'افتح التقويم لرؤية المناوبات والمدخلات حسب اليوم. في الدورة أنشئ أيام الدوام حسب أيام الأسبوع وعدّل أياماً مفردة.',
  'Where are my statistics?': 'أين إحصائياتي؟',
  'Analytics in the notebooks shows cases by specialty, most frequent diagnoses and activity over the last 16 weeks. Counts show what you saw and did, not competence by themselves.': 'تعرض التحليلات في الدفاتر الحالات حسب التخصص وأكثر التشخيصات تكراراً ونشاطك في آخر 16 أسبوعاً. الأعداد تبين ما رأيته وفعلته ولا تثبت الكفاءة وحدها.',
  'What are reflections, achievements and QI?': 'ما هي التأملات والإنجازات وتحسين الجودة؟',
  'The notebooks hold reflections, achievements, quality improvement projects and evidence notes for your portfolio. They can count towards goals.': 'تضم الدفاتر التأملات والإنجازات ومشاريع تحسين الجودة وملاحظات الأدلة لملفك. يمكن أن تُحتسب ضمن الأهداف.',
  'Can I search PubMed?': 'هل يمكنني البحث في PubMed؟',
  'Yes, in the notebooks open PubMed search (needs internet). Save useful papers to your evidence notes. The rest of the app works offline.': 'نعم، في الدفاتر افتح البحث في PubMed (يحتاج إنترنت). احفظ الأوراق المفيدة في ملاحظات الأدلة. بقية التطبيق يعمل دون إنترنت.',
  'Does MedLog work without internet?': 'هل يعمل التطبيق دون إنترنت؟',
  'Yes. Cases, library packs you downloaded, quizzes, review, planner and exports all work offline. Only downloading packs, PubMed and the optional AI features need internet.': 'نعم. الحالات وحزم المكتبة المنزلة والاختبارات والمراجعة والمخطط والتصدير كلها تعمل دون إنترنت. فقط تنزيل الحزم وPubMed وميزات الذكاء الاصطناعي الاختيارية تحتاج إنترنت.',
  'How do I try the app with demo data?': 'كيف أجرب التطبيق ببيانات تجريبية؟',
  'Settings, Load demo data adds fictional records to try every screen. Demo data is never included in backups and Remove demo data deletes it.': 'الإعدادات، تحميل بيانات تجريبية يضيف سجلات وهمية لتجربة كل الشاشات. لا تدخل البيانات التجريبية في النسخ الاحتياطية وإزالتها تحذفها.',
  'How do I turn on the AI assistant?': 'كيف أفعّل مساعد الذكاء الاصطناعي؟',
  'AI is optional and off by default. In Settings, AI, turn it on and paste your own provider key (free tiers exist). The key stays on this phone. AI only suggests; nothing is saved until you confirm.': 'الذكاء الاصطناعي اختياري ومعطل افتراضياً. في الإعدادات، الذكاء الاصطناعي، فعّله والصق مفتاحك الخاص (توجد باقات مجانية). يبقى المفتاح على هذا الهاتف. يقترح فقط ولا يُحفظ شيء حتى تؤكد.',
  'What is sent to the AI?': 'ماذا يُرسل إلى الذكاء الاصطناعي؟',
  'Help questions send only your question. Case features send a de-identified summary (no names, code, dates, hospital or images) that you preview first. A case marked Never send to AI is never sent. Every request is logged on your phone.': 'أسئلة المساعدة ترسل سؤالك فقط. ميزات الحالة ترسل ملخصاً مجهول الهوية (دون أسماء أو رمز أو تواريخ أو مستشفى أو صور) تعاينه قبل الإرسال. الحالة المعلّمة بعدم الإرسال لا تُرسل أبداً. يُسجَّل كل طلب على هاتفك.',
  'What can the AI case assistant do?': 'ماذا يفعل مساعد الحالة بالذكاء الاصطناعي؟',
  'In the case menu choose AI assistant: discuss your case (differential for your consideration), Socratic questions, suggest fields from a note, a missing-fields check, an I-PASS handover and learning points. It never replaces your judgement.': 'من قائمة الحالة اختر مساعد الذكاء الاصطناعي: مناقشة الحالة (تشخيص تفريقي للاعتبار) وأسئلة سقراطية واقتراح حقول من ملاحظة وفحص الحقول الناقصة وملخص تسليم I-PASS ونقاط تعلم. لا يحل محل حكمك.',
  'How do I stop one case from ever going to AI?': 'كيف أمنع حالة من الإرسال إلى الذكاء الاصطناعي؟',
  'In the case Info tab turn on Never send this case to AI. All AI features then skip that case.': 'في تبويب معلومات الحالة فعّل عدم إرسال هذه الحالة إلى الذكاء الاصطناعي. ستتخطاها كل ميزات الذكاء الاصطناعي.',
  'Does the AI change my case by itself?': 'هل يغير الذكاء الاصطناعي حالتي من تلقاء نفسه؟',
  'No. Suggested field values appear as a list with checkboxes. Nothing is saved until you tap Apply, applied fields are marked as AI-suggested, and you can undo.': 'لا. تظهر القيم المقترحة في قائمة بمربعات اختيار. لا يُحفظ شيء حتى تضغط تطبيق، وتُعلَّم الحقول المطبقة بأنها مقترحة بالذكاء الاصطناعي ويمكنك التراجع.',
  'What are the week and rotation summaries?': 'ما هي ملخصات الأسبوع والدورة؟',
  'Home shows your week in numbers computed on the phone. With AI on, a short narrative can be written from those counts only (no case content). Rotation PDFs can include an AI paragraph clearly marked as AI-generated.': 'تعرض الرئيسية أسبوعك بالأرقام محسوبة على الهاتف. مع تفعيل الذكاء الاصطناعي يمكن كتابة سرد قصير من هذه الأعداد فقط (دون محتوى الحالات). يمكن أن تتضمن ملفات PDF للدورة فقرة معلّمة بأنها من الذكاء الاصطناعي.',
  'Any tips to use MedLog every day?': 'هل من نصائح لاستخدام التطبيق يومياً؟',
  'Log a quick case right after seeing the patient, write one pearl a day, do a short review session, and back up once a week. Use the case code, never names.': 'سجّل حالة سريعة بعد رؤية المريض مباشرة واكتب درة واحدة يومياً وأجرِ جلسة مراجعة قصيرة وانسخ احتياطياً مرة أسبوعياً. استخدم رمز الحالة دون أسماء.',
  'What is the case code?': 'ما هو رمز الحالة؟',
  'Each case gets a code such as IM-0001. Use it to recognise a patient instead of a name. It is shown in shared presentations but never sent to AI.': 'تحصل كل حالة على رمز مثل IM-0001. استخدمه لتتعرف على المريض بدل الاسم. يظهر في العروض المشاركة ولا يُرسل إلى الذكاء الاصطناعي.',
  'Can I find similar or related cases?': 'هل يمكنني إيجاد حالات مشابهة؟',
  'Case menu: Similar & related lists your other cases with the same diagnosis or tags, and Compare with another case shows them side by side.': 'قائمة الحالة: مشابهة وذات صلة تعرض حالاتك الأخرى بنفس التشخيص أو الوسوم، ومقارنة مع حالة أخرى تعرضهما جنباً إلى جنب.',
  'Can I read about my case diagnosis in the library?': 'هل أقرأ عن تشخيص حالتي في المكتبة؟',
  'Case menu: Read about this in the library finds matching articles from your downloaded packs.': 'قائمة الحالة: القراءة عن هذا في المكتبة تجد المقالات المطابقة من الحزم المنزلة.',
  'Is my data synced to the cloud?': 'هل تُزامن بياناتي مع السحابة؟',
  'No. Everything is stored on this phone only. That is why regular encrypted backups matter.': 'لا. كل شيء مخزن على هذا الهاتف فقط. لذلك النسخ الاحتياطي المشفر المنتظم مهم.',
  'Where is the cheat sheet or glance view?': 'أين الملخصات السريعة؟',
  'Many library articles have a quick sheet view with the key points. Turn it on in the article menu or in Library settings.': 'تحتوي كثير من مقالات المكتبة على عرض ملخص بالنقاط الأساسية. فعّله من قائمة المقال أو إعدادات المكتبة.',
  'Is there a medical dictionary?': 'هل يوجد قاموس طبي؟',
  'Yes, the Library has a Dictionary for medical terms that works offline, including Arabic equivalents.': 'نعم، في المكتبة قاموس للمصطلحات الطبية يعمل دون إنترنت ويتضمن المقابلات العربية.',
  'AI is not available right now. The local tools still work.': 'الذكاء الاصطناعي غير متاح الآن. الأدوات المحلية تعمل كالمعتاد.',
  'AI suggestions are for your consideration only. They can be wrong or incomplete. You are responsible for every clinical decision: check the library, the guidelines and your senior.': 'اقتراحات الذكاء الاصطناعي للاعتبار فقط. قد تكون خاطئة أو ناقصة. أنت المسؤول عن كل قرار سريري: راجع المكتبة والإرشادات الطبية وطبيبك الأقدم.',
  'This case is marked "Never send this case to AI". Turn it off in the case Info tab to use these tools.': 'هذه الحالة معلّمة بعبارة "عدم إرسال هذه الحالة إلى الذكاء الاصطناعي". أوقف هذا الخيار في تبويب المعلومات لاستخدام هذه الأدوات.',
  'AI is off. MedLog works fully without it. You can turn on the optional assistant in Settings.': 'الذكاء الاصطناعي متوقف. يعمل MedLog بالكامل بدونه. يمكنك تفعيل المساعد الاختياري من الإعدادات.',
  'Open AI settings': 'افتح إعدادات الذكاء الاصطناعي',
  'You are offline. Saved answers can still be read; new AI requests need internet.': 'أنت غير متصل. ما زال بإمكانك قراءة الإجابات المحفوظة؛ الطلبات الجديدة تحتاج إلى إنترنت.',
  'What will be sent': 'ما الذي سيُرسل',
  'Only these de-identified fields. You see them again and can untick any before sending.': 'هذه الحقول المجهولة الهوية فقط. ستراها مرة أخرى ويمكنك إلغاء تحديد أي منها قبل الإرسال.',
  'Removed before sending': 'أُزيل قبل الإرسال',
  'Never sent: code, names, initials, dates, hospital or doctor names, images.': 'لا يُرسل أبداً: الرمز والأسماء والأحرف الأولى والتواريخ وأسماء المستشفيات أو الأطباء والصور.',
  'This case has no content to discuss yet. Add the history and examination first.': 'لا يوجد في هذه الحالة محتوى للمناقشة بعد. أضف القصة والفحص أولاً.',
  'The answer could not be read. Try again.': 'تعذرت قراءة الإجابة. حاول مرة أخرى.',
  'Discuss my case': 'ناقش حالتي',
  'For your consideration': 'للاعتبار',
  'Red flags to exclude': 'علامات الخطر المطلوب استبعادها',
  'Do not miss': 'لا يجوز إغفالها',
  'Focused history to consider': 'قصة مرضية مركزة للاعتبار',
  'Focused examination to consider': 'فحص سريري مركز للاعتبار',
  'Investigations to consider': 'فحوصات للاعتبار',
  'What would change management': 'ما الذي قد يغيّر الخطة العلاجية',
  'For (from your case)': 'مع (من حالتك)',
  'Against / missing': 'ضد / ناقص',
  'Your diagnoses: read about them': 'تشخيصاتك: اقرأ عنها',
  'more likely': 'أكثر احتمالاً',
  'possible': 'محتمل',
  'less likely': 'أقل احتمالاً',
  'Read about it': 'اقرأ عنه',
  'The tutor asks you one question at a time about this case (your differential, what you would order...). You answer, then you get feedback and the next question. Up to {n} questions.': 'يطرح عليك المعلّم سؤالاً واحداً في كل مرة عن هذه الحالة (تشخيصك التفريقي، ما الذي ستطلبه...). تجيب ثم تحصل على تعليق والسؤال التالي. حتى {n} أسئلة.',
  'Start Socratic mode': 'ابدأ الوضع السقراطي',
  'Answer {a} of {b}': 'الإجابة {a} من {b}',
  'Send answer': 'أرسل الإجابة',
  'Start again': 'ابدأ من جديد',
  'You': 'أنت',
  'Tutor (AI)': 'المعلّم (ذكاء اصطناعي)',
  'Questions to ask yourself': 'أسئلة اسألها لنفسك',
  'Write or paste a longer note first.': 'اكتب ملاحظة أطول أو الصقها أولاً.',
  'Nothing new to suggest from this note.': 'لا شيء جديد لاقتراحه من هذه الملاحظة.',
  '{n} fields applied': 'تم تطبيق {n} من الحقول',
  'Undone.': 'تم التراجع.',
  'Paste or dictate a free-text note (use the microphone key of your keyboard). The note is cleaned and shown to you before anything is sent. Nothing is saved until you tap Apply.': 'الصق ملاحظة نصية حرة أو أمْلِها (استخدم زر الميكروفون في لوحة المفاتيح). تُنظَّف الملاحظة وتُعرض عليك قبل إرسال أي شيء. لا يُحفظ شيء حتى تضغط تطبيق.',
  'Clinical note': 'ملاحظة سريرية',
  'Show what will be sent': 'اعرض ما سيُرسل',
  'Suggest fields': 'اقترح الحقول',
  'Cleaned note (this is what leaves the phone)': 'الملاحظة بعد التنظيف (هذا ما يغادر الهاتف)',
  'Suggested values': 'القيم المقترحة',
  'Tick what you want to apply. Fields that already have text are not ticked: ticking replaces them.': 'حدد ما تريد تطبيقه. الحقول التي تحتوي نصاً لا تكون محددة: تحديدها يستبدل النص.',
  'Now': 'الحالي',
  'Replaces what you wrote': 'يستبدل ما كتبته',
  'Apply selected ({n})': 'طبّق المحدد ({n})',
  'Procedures mentioned (log them separately)': 'إجراءات مذكورة (سجّلها بشكل منفصل)',
  'Fields filled from AI suggestions': 'حقول مملوءة من اقتراحات الذكاء الاصطناعي',
  'Without AI: use "Quick fill from specialty template" in the case menu, or type directly in the case tabs.': 'بدون الذكاء الاصطناعي: استخدم "ملء سريع من قالب التخصص" في قائمة الحالة، أو اكتب مباشرة في تبويبات الحالة.',
  'Tag added: {t}': 'أُضيف الوسم: {t}',
  'Specialty set: {t}': 'تم تعيين التخصص: {t}',
  'No missing or inconsistent fields found.': 'لم يُعثر على حقول ناقصة أو متعارضة.',
  '{n} things to check': '{n} أمور للتحقق منها',
  'These checks run on your phone, with no internet and no AI.': 'تعمل هذه الفحوصات على هاتفك دون إنترنت ودون ذكاء اصطناعي.',
  'Suggested tags': 'وسوم مقترحة',
  'No tag suggestions from your own tags yet.': 'لا توجد اقتراحات وسوم من وسومك بعد.',
  'Suggest specialty and tags': 'اقترح التخصص والوسوم',
  'Built on your phone from the case fields. It uses the case code, never a name.': 'يُبنى على هاتفك من حقول الحالة. يستخدم رمز الحالة وليس الاسم أبداً.',
  'Draft contingency plan': 'صياغة خطة الطوارئ المحتملة',
  'Only the de-identified fields are sent, and you preview them first. The AI lines are marked [AI draft]: check them.': 'تُرسل الحقول المجهولة الهوية فقط وتعاينها أولاً. أسطر الذكاء الاصطناعي معلّمة بـ [AI draft]: راجعها.',
  'These cards already exist.': 'هذه البطاقات موجودة مسبقاً.',
  '{n} review cards made.': 'تم إنشاء {n} من بطاقات المراجعة.',
  'Reflect on this case': 'تأمل في هذه الحالة',
  'AI-generated questions: prompts only, the answers are yours to write.': 'أسئلة مولّدة بالذكاء الاصطناعي: محفزات فقط، والإجابات من كتابتك.',
  'Questions made from your case. Answer them in "What I learned".': 'أسئلة مصاغة من حالتك. أجب عنها في "ما تعلمته".',
  'Ask AI for 3 questions': 'اطلب 3 أسئلة من الذكاء الاصطناعي',
  'Make review cards from this case': 'أنشئ بطاقات مراجعة من هذه الحالة',
  'Add a diagnosis, red flags or "What I learned" to make cards.': 'أضف تشخيصاً أو علامات خطر أو "ما تعلمته" لإنشاء بطاقات.',
  'Cards are phrased from your own entries and join the spaced review. No names or code are in the question.': 'تُصاغ البطاقات من مدخلاتك وتنضم إلى المراجعة المتباعدة. لا أسماء ولا رمز في السؤال.',
  'Make review cards': 'أنشئ بطاقات المراجعة',
  'Discuss': 'ناقش',
  'Socratic': 'سقراطي',
  'Fields': 'الحقول',
  'Check': 'فحص',
  'Handover': 'تسليم',
  'Week summary': 'ملخص الأسبوع',
  'Write a short summary': 'اكتب ملخصاً قصيراً',
  'Only the numbers above are sent, never case content.': 'تُرسل الأرقام أعلاه فقط، وليس محتوى الحالات أبداً.',
  'I could not find this in the help. Try other words, or browse all topics below.': 'لم أجد هذا في المساعدة. جرّب كلمات أخرى أو تصفح كل المواضيع أدناه.',
  'Explain simply with AI': 'اشرح ببساطة بالذكاء الاصطناعي',
  'Only your question and the help text above are sent. No case data.': 'يُرسل سؤالك ونص المساعدة أعلاه فقط. لا بيانات حالات.',
  'Ask how to do something in MedLog. Answers come from the built-in help and work offline.': 'اسأل كيف تنجز شيئاً في MedLog. تأتي الإجابات من المساعدة المدمجة وتعمل دون إنترنت.',
  'All topics': 'كل المواضيع',
  'How do I...?': 'كيف أ...؟',
  'Chief complaint is empty.': 'الشكوى الرئيسية فارغة.',
  'History of present illness is empty.': 'قصة المرض الحالي فارغة.',
  'Age group is not set.': 'الفئة العمرية غير محددة.',
  'Setting is not set.': 'مكان الرعاية غير محدد.',
  'Specialty is not set.': 'التخصص غير محدد.',
  'Allergies are not recorded (write "none" or mark Unknown).': 'الحساسية غير مسجلة (اكتب "لا يوجد" أو علّمها غير معروفة).',
  'No vital signs recorded.': 'لم تُسجل علامات حيوية.',
  'Vital signs are incomplete (BP, HR, Temp, RR, SpO2).': 'العلامات الحيوية غير مكتملة (BP, HR, Temp, RR, SpO2).',
  'No examination recorded.': 'لم يُسجل فحص سريري.',
  'No working or final diagnosis yet.': 'لا يوجد تشخيص مبدئي أو نهائي بعد.',
  'Diagnosis without reasoning, problem list or differential.': 'تشخيص دون استدلال أو قائمة مشكلات أو تشخيص تفريقي.',
  'No plan / management recorded.': 'لم تُسجل خطة / علاج.',
  'Case is closed but has no final diagnosis.': 'الحالة مغلقة لكن لا يوجد تشخيص نهائي.',
  'Case is closed but has no outcome or disposition.': 'الحالة مغلقة لكن لا توجد نتيجة أو وجهة خروج.',
  'No learning point written (What I learned).': 'لم تُكتب نقطة تعلم (ما تعلمته).',
  'Case is closed but an investigation is still Pending.': 'الحالة مغلقة لكن ما زال هناك فحص قيد الانتظار.',
  'A given medication has no dose / route / frequency.': 'دواء معطى دون جرعة / طريقة / تكرار.',
  'Specialty is Pediatrics but age group is Adult.': 'التخصص أطفال لكن الفئة العمرية بالغ.',
  'Age group is Child but the specialty is {s}.': 'الفئة العمرية طفل لكن التخصص {s}.',
  'Sex is M but obstetric fields are filled.': 'الجنس ذكر لكن حقول التوليد مملوءة.',
  'Status is Draft but a final diagnosis is entered.': 'الوضع مسودة لكن أُدخل تشخيص نهائي.',
  'An outcome is written but the status is still {s}.': 'كُتبت نتيجة لكن الوضع ما زال {s}.',
  'Blood pressure is not in the form 120/80.': 'ضغط الدم ليس بصيغة 120/80.',
  'Blood pressure: systolic is not higher than diastolic.': 'ضغط الدم: الانقباضي ليس أعلى من الانبساطي.',
  '{name} value looks implausible: {v}.': 'قيمة {name} تبدو غير معقولة: {v}.',
  'Heart rate': 'معدل النبض',
  'Temperature': 'درجة الحرارة',
  'Respiratory rate': 'معدل التنفس',
  'Blood sugar': 'سكر الدم',
  'Low SpO2 recorded but no problem or diagnosis mentions it.': 'سُجّل انخفاض في SpO2 لكن لا مشكلة أو تشخيص يذكره.',
  '{n} cases in {d} days': '{n} حالات في {d} أيام',
  '{n} procedures': '{n} إجراءات',
  '{n} performed': '{n} منفذة',
  'Your own identifier or name (e.g. hospital, supervisor, code)': 'معرّف أو اسم خاص بك (مثل المستشفى أو المشرف أو الرمز)',
  'Exact dates': 'تواريخ دقيقة',
  'Saved answer from earlier': 'إجابة محفوظة من قبل',
  'Never send this case to AI': 'عدم إرسال هذه الحالة إلى الذكاء الاصطناعي',
  'The AI assistant skips this case completely.': 'يتخطى مساعد الذكاء الاصطناعي هذه الحالة تماماً.',
  'Add an AI summary paragraph': 'أضف فقرة ملخص بالذكاء الاصطناعي',
  'Written from the counts only, marked AI-generated in the PDF. Needs internet.': 'تُكتب من الأعداد فقط وتُعلَّم في ملف PDF بأنها من الذكاء الاصطناعي. تحتاج إنترنت.',
  'AI-generated summary': 'ملخص مولّد بالذكاء الاصطناعي',
  'Written by AI from the counts above, not reviewed. Check before use.': 'كتبه الذكاء الاصطناعي من الأعداد أعلاه ولم تتم مراجعته. تحقق منه قبل الاستخدام.',
  'AI answers': 'إجابات الذكاء الاصطناعي',
  'Privacy': 'الخصوصية',
  'The master switch. When it is off, no AI button appears anywhere and nothing is ever sent. The app works fully without AI and without internet.': 'المفتاح الرئيسي. عند إيقافه لا يظهر أي زر للذكاء الاصطناعي في أي مكان ولا يُرسل أي شيء. يعمل التطبيق بالكامل دون ذكاء اصطناعي ودون إنترنت.',
  'Practice questions drafted from your library topics.': 'أسئلة تدريبية تُصاغ من مواضيع مكتبتك.',
  'Who answers your questions. You use your own key.': 'الجهة التي تجيب عن أسئلتك. تستخدم مفتاحك الخاص.',
  'Choose the company whose AI answers. You create a key on their website and paste it here. The key stays on this phone and is sent only to that company. Gemini has a free tier, which is a good place to start.': 'اختر الشركة التي يجيب ذكاؤها الاصطناعي. تنشئ مفتاحاً على موقعها وتلصقه هنا. يبقى المفتاح على هذا الهاتف ويُرسل إلى تلك الشركة فقط. لدى Gemini باقة مجانية وهي بداية جيدة.',
  'The exact AI model used. Automatic picks a cheap and fast one that is good enough for study questions. Pick another from the list if your key gives access to a stronger model.': 'النموذج المستخدم تحديداً. يختار الوضع التلقائي نموذجاً رخيصاً وسريعاً يكفي لأسئلة المذاكرة. اختر نموذجاً آخر من القائمة إن كان مفتاحك يتيح نموذجاً أقوى.',
  'Switch this on to let the app use AI for this purpose. When it is off, the matching AI button is hidden and nothing is sent for it.': 'فعّل هذا الخيار ليستخدم التطبيق الذكاء الاصطناعي لهذا الغرض. عند إيقافه يُخفى زر الذكاء الاصطناعي المقابل ولا يُرسل شيء له.',
  'Answer language': 'لغة الإجابة',
  'English is the default.': 'الإنجليزية هي الافتراضية.',
  'English: answers in English. Mixed: the explanation is in Arabic and medical terms, drug names and doses stay in English. Arabic: answers in Arabic. Medical terms are always safer to keep in English.': 'الإنجليزية: الإجابات بالإنجليزية. مختلطة: الشرح بالعربية وتبقى المصطلحات الطبية وأسماء الأدوية والجرعات بالإنجليزية. العربية: الإجابات بالعربية. الأسلم دائماً إبقاء المصطلحات الطبية بالإنجليزية.',
  'Arabic explanation, English medical terms': 'شرح بالعربية ومصطلحات طبية بالإنجليزية',
  'Arabic': 'العربية',
  'Answer length': 'طول الإجابة',
  'How much detail you get.': 'مقدار التفصيل الذي تحصل عليه.',
  'Brief: a few lines, for a quick check. Standard: the key points in a structured answer. Comprehensive: a full overview with differentials, management and references. Longer answers use more of your daily quota.': 'موجزة: بضعة أسطر لمراجعة سريعة. عادية: النقاط الأساسية في إجابة منظمة. شاملة: عرض كامل مع التشخيص التفريقي والتدبير والمراجع. الإجابات الأطول تستهلك جزءاً أكبر من حصتك اليومية.',
  'Brief': 'موجزة',
  'Standard': 'عادية',
  'Comprehensive': 'شاملة',
  'Where answers come from': 'مصدر الإجابات',
  'The kind of source the AI should rely on.': 'نوع المصدر الذي يعتمد عليه الذكاء الاصطناعي.',
  'Trusted web: the AI is told to use the websites in the list below (guideline bodies, journals). My library: only the courses installed on this phone. Model knowledge: the AI answers from memory, with no sources. Custom: only the sites you add yourself.': 'الويب الموثوق: يُطلب من الذكاء الاصطناعي استخدام المواقع في القائمة أدناه (جهات الإرشادات والمجلات). مكتبتي: المقررات المثبتة على هذا الهاتف فقط. معرفة النموذج: يجيب من الذاكرة دون مصادر. مخصص: المواقع التي تضيفها بنفسك فقط.',
  'Trusted web': 'الويب الموثوق',
  'Guideline and journal sites from the list below': 'مواقع الإرشادات والمجلات من القائمة أدناه',
  'My library': 'مكتبتي',
  'Only the courses installed on this phone': 'المقررات المثبتة على هذا الهاتف فقط',
  'Model knowledge': 'معرفة النموذج',
  'No web, no sources': 'بلا ويب وبلا مصادر',
  'Only the sites you add': 'المواقع التي تضيفها فقط',
  'Use the provider\'s live web search when available': 'استخدم بحث الويب المباشر للمزوّد عند توفره',
  'Gemini, Claude and OpenAI can look things up online.': 'يمكن لـ Gemini وClaude وOpenAI البحث على الإنترنت.',
  'When the provider has its own web-search tool, the AI can read current pages instead of relying on memory. The app still checks that every cited link belongs to your allowed list and hides the ones that do not. It needs internet and may use more of your quota.': 'عندما يملك المزوّد أداة بحث ويب خاصة به، يستطيع الذكاء الاصطناعي قراءة صفحات حديثة بدل الاعتماد على الذاكرة. ما زال التطبيق يتحقق من أن كل رابط مستشهد به ضمن قائمتك المسموح بها ويخفي الروابط الأخرى. يحتاج إلى الإنترنت وقد يستهلك حصة أكبر.',
  'Region for guidelines': 'المنطقة لاختيار الإرشادات',
  'For example: Jordan, Middle East, UK.': 'مثال: الأردن، الشرق الأوسط، المملكة المتحدة.',
  'Guidelines differ between countries (drug names, doses, local protocols). A region hint lets the AI choose the guidelines that fit where you work. Leave it empty for international guidelines. Only this short text is sent, never your location.': 'تختلف الإرشادات بين الدول (أسماء الأدوية والجرعات والبروتوكولات المحلية). يتيح تلميح المنطقة للذكاء الاصطناعي اختيار الإرشادات التي تناسب مكان عملك. اتركه فارغاً للإرشادات الدولية. يُرسل هذا النص القصير فقط ولا يُرسل موقعك أبداً.',
  'Region (optional)': 'المنطقة (اختياري)',
  'Show citations': 'إظهار المراجع',
  'List the sources under each answer.': 'عرض المصادر أسفل كل إجابة.',
  'Shows the references the AI used under every answer, as links you can open. Links that are not on your allowed list are marked as unverified. Turn it off for a cleaner screen.': 'يعرض المراجع التي استخدمها الذكاء الاصطناعي أسفل كل إجابة كروابط يمكنك فتحها. الروابط غير الموجودة في قائمتك المسموح بها تُعلَّم بأنها غير موثقة. أوقفه لشاشة أنظف.',
  'How answers look': 'شكل الإجابات',
  'Cards or plain text.': 'بطاقات أو نص عادي.',
  'Cards: the answer is split into labelled sections (overview, management, red flags, references) that are easy to scan. Plain text: one continuous text, closer to a chat.': 'بطاقات: تُقسَّم الإجابة إلى أقسام معنونة (نظرة عامة، تدبير، علامات الخطر، مراجع) يسهل تصفحها. نص عادي: نص متصل واحد أقرب إلى المحادثة.',
  'Cards': 'بطاقات',
  'Plain text': 'نص عادي',
  'Daily request limit': 'الحد اليومي للطلبات',
  'A guard on top of your provider quota.': 'حماية إضافية فوق حصة المزوّد.',
  'The most AI requests the app will send in one day. It protects a free key from running out and avoids surprise costs on a paid key. Answers already saved on the phone do not count.': 'أقصى عدد من طلبات الذكاء الاصطناعي يرسله التطبيق في اليوم. يحمي المفتاح المجاني من النفاد ويمنع تكاليف مفاجئة في المفتاح المدفوع. الإجابات المحفوظة على الهاتف لا تُحتسب.',
  'Floating button': 'الزر العائم',
  'Floating Ask AI button': 'زر اسأل الذكاء الاصطناعي العائم',
  'A small draggable button on the main screens.': 'زر صغير قابل للسحب على الشاشات الرئيسية.',
  'A small button you can drag. It offers quick AI actions that fit the screen you are on. It only appears when the AI assistant is on and has a key.': 'زر صغير يمكنك سحبه. يقترح إجراءات سريعة تناسب الشاشة التي أنت عليها. لا يظهر إلا عندما يكون المساعد مفعّلاً ولديه مفتاح.',
  'Button side': 'جهة الزر',
  'Where the button rests.': 'مكان استقرار الزر.',
  'Start is the left edge in English and the right edge in Arabic. End is the opposite side. You can still drag the button anywhere and it remembers its height.': 'البداية هي الحافة اليسرى في الإنجليزية واليمنى في العربية، والنهاية هي الجهة المقابلة. ما زال بإمكانك سحب الزر إلى أي مكان وسيتذكر ارتفاعه.',
  'End': 'النهاية',
  'Show the button on': 'إظهار الزر في',
  'Choose the screens.': 'اختر الشاشات.',
  'Switch off the screens where the floating button gets in the way. It stays available on the others.': 'أوقف الشاشات التي يزعجك فيها الزر العائم. يبقى متاحاً في الباقي.',
  'Articles': 'المقالات',
  'Quizzes': 'الاختبارات',
  'Lets the app add short passages from the courses installed on this phone to your question, so the answer is based on them. These are public, licensed texts, not your own notes.': 'يتيح للتطبيق إضافة مقاطع قصيرة من المقررات المثبتة على هذا الهاتف إلى سؤالك لتستند الإجابة إليها. هذه نصوص عامة مرخصة وليست ملاحظاتك الخاصة.',
  'Lets the case assistant send a short summary of a case (age band, sex, findings, labs in words). Names, ids, phones, addresses, hospital or doctor names, images and exact dates are removed first. You see and approve every summary before it leaves the phone.': 'يتيح لمساعد الحالات إرسال ملخص قصير لحالة (الفئة العمرية، الجنس، الموجودات، التحاليل بالكلمات). تُزال أولاً الأسماء والأرقام التعريفية والهواتف والعناوين وأسماء المستشفيات أو الأطباء والصور والتواريخ الدقيقة. ترى كل ملخص وتوافق عليه قبل أن يغادر الهاتف.',
  'See exactly what leaves the phone.': 'شاهد بالضبط ما يغادر الهاتف.',
  'Before every send: you review the text each time. Once per session: you review the first request after opening the app, then the next ones in the same session go straight through.': 'قبل كل إرسال: تراجع النص في كل مرة. مرة لكل جلسة: تراجع أول طلب بعد فتح التطبيق ثم تُرسل الطلبات التالية في الجلسة نفسها مباشرة.',
  'What is never sent': 'ما لا يُرسل أبداً',
  'Names, ids, images, exact dates, whole notes.': 'الأسماء والأرقام التعريفية والصور والتواريخ الدقيقة والملاحظات كاملة.',
  'These are removed or never included, whatever you choose: patient names and ids, phone numbers, emails, addresses, hospital and doctor names, images, exact dates and whole free-text notes. A case marked "never send to AI" is blocked completely. The cleaning is automatic and careful, but not perfect, so read the preview.': 'تُزال هذه أو لا تُضمَّن أبداً مهما اخترت: أسماء المرضى وأرقامهم التعريفية وأرقام الهواتف والبريد الإلكتروني والعناوين وأسماء المستشفيات والأطباء والصور والتواريخ الدقيقة والملاحظات الحرة كاملة. الحالة المعلَّمة "لا تُرسل للذكاء الاصطناعي" محجوبة تماماً. التنظيف تلقائي ودقيق لكنه ليس مثالياً، لذا اقرأ المعاينة.',
  'Enter a website such as nice.org.uk (not already in the list).': 'أدخل موقعاً مثل nice.org.uk (غير موجود في القائمة).',
  'My own sites': 'مواقعي الخاصة',
  'Allowed websites': 'المواقع المسموح بها',
  'The app verifies cited links against this list and hides the others.': 'يتحقق التطبيق من الروابط المستشهد بها مقابل هذه القائمة ويخفي الباقي.',
  'Only the sites you add here are used in Custom mode. The app checks every link the AI cites against this list and marks links from other sites as unverified. If the list is empty, the default trusted list is used.': 'تُستخدم المواقع التي تضيفها هنا فقط في الوضع المخصص. يفحص التطبيق كل رابط يستشهد به الذكاء الاصطناعي مقابل هذه القائمة ويعلّم روابط المواقع الأخرى بأنها غير موثقة. إن كانت القائمة فارغة تُستخدم القائمة الموثوقة الافتراضية.',
  'Websites the AI may rely on and cite: guideline bodies, health agencies and journals. The app checks every link the AI cites against this list and marks links from other sites as unverified. Add or remove sites, or restore the default list.': 'مواقع يجوز للذكاء الاصطناعي الاعتماد عليها والاستشهاد بها: جهات الإرشادات والهيئات الصحية والمجلات. يفحص التطبيق كل رابط يستشهد به مقابل هذه القائمة ويعلّم روابط المواقع الأخرى بأنها غير موثقة. أضف المواقع أو احذفها أو استعد القائمة الافتراضية.',
  'No sites yet: the default trusted list is used.': 'لا مواقع بعد: تُستخدم القائمة الموثوقة الافتراضية.',
  'Reset to the default list': 'استعادة القائمة الافتراضية',
  'Suggest settings for me': 'اقترح لي الإعدادات',
  'Download the {course} course': 'نزّل مقرر {course}',
  'It matches your current rotation and is not on this phone yet.': 'يطابق تدريبك الحالي وليس على هذا الهاتف بعد.',
  'Download Clinical essentials': 'نزّل Clinical essentials',
  '{n} Core 250 topics of your rotation have no article on this phone yet.': '{n} من مواضيع Core 250 في تدريبك ليس لها مقال على هذا الهاتف بعد.',
  'Set the article text size to 100%': 'اضبط حجم نص المقالات على 100%',
  'On a narrow screen ({w} px wide) large text makes very short lines.': 'على شاشة ضيقة (عرضها {w} بكسل) يجعل النص الكبير الأسطر قصيرة جداً.',
  'Your phone text size is already large; the article size adds to it.': 'حجم نص هاتفك كبير أصلاً، وحجم المقالات يُضاف إليه.',
  'Set the article text size to 110%': 'اضبط حجم نص المقالات على 110%',
  'The screen is wide ({w} px); a larger size is easier to read.': 'الشاشة عريضة ({w} بكسل)، والحجم الأكبر أسهل في القراءة.',
  'Free some space': 'حرّر بعض المساحة',
  'Only {free} left on the phone. Pictures cache: {cache}.': 'لم يتبق سوى {free} على الهاتف. ذاكرة الصور المؤقتة: {cache}.',
  'Clear the downloaded pictures cache': 'امسح ذاكرة الصور المنزّلة المؤقتة',
  'The pictures cache uses {cache}.': 'تستخدم ذاكرة الصور المؤقتة {cache}.',
  'Your courses and pictures are large ({size}); this avoids using mobile data by accident.': 'مقرراتك وصورك كبيرة ({size})، وهذا يمنع استخدام بيانات الجوال بالخطأ.',
  'Turn off AI features you never used': 'أوقف ميزات الذكاء الاصطناعي التي لم تستخدمها',
  'Not used so far: {list}.': 'لم تُستخدم حتى الآن: {list}.',
  'The AI explanation is not available now. The suggestions above still work.': 'شرح الذكاء الاصطناعي غير متاح الآن. ما زالت الاقتراحات أعلاه تعمل.',
  'Looks at how you use MedLog on this phone (rotation, courses, screen, storage). Nothing changes until you tap Apply, and you can undo.': 'ينظر في كيفية استخدامك MedLog على هذا الهاتف (التدريب والمقررات والشاشة والتخزين). لا يتغير شيء حتى تضغط تطبيق، ويمكنك التراجع.',
  'Your settings already look good for how you use the app.': 'إعداداتك مناسبة أصلاً لطريقة استخدامك للتطبيق.',
  'Apply all': 'تطبيق الكل',
  'Explain this option': 'اشرح هذا الخيار',
  'Size of the text inside library articles.': 'حجم النص داخل مقالات المكتبة.',
  'Changes only the text of library articles and study sheets, not the whole app. The phone text size (Android settings) is applied on top of it.': 'يغيّر نص مقالات المكتبة وأوراق المذاكرة فقط وليس التطبيق كله. يُطبَّق حجم نص الهاتف (إعدادات أندرويد) فوقه.',
  'A little bigger and heavier, easier in bright light.': 'أكبر وأثقل قليلاً، وأسهل في الضوء الساطع.',
  'Makes article text about 10% larger and a bit heavier. It helps when reading on a phone in bright light or during a shift.': 'يجعل نص المقالات أكبر بنحو 10% وأثقل قليلاً. يفيد عند القراءة على الهاتف في ضوء ساطع أو أثناء المناوبة.',
  'Plain: text only. Light: callout cards. Rich: cards, icons and colour.': 'بسيط: نص فقط. خفيف: بطاقات تنبيه. غني: بطاقات وأيقونات وألوان.',
  'The study sheet is the structured view of an article. Plain keeps simple text. Light adds coloured cards for doses and red flags. Rich adds more colour, icons and highlighted key sentences. The preview below changes as you choose.': 'ورقة المذاكرة هي العرض المنظم للمقال. البسيط يبقي نصاً عادياً. الخفيف يضيف بطاقات ملونة للجرعات وعلامات الخطر. الغني يضيف ألواناً وأيقونات أكثر وجملاً أساسية مظللة. تتغير المعاينة أدناه حسب اختيارك.',
  'Plain': 'بسيط',
  'Rich': 'غني',
  'Finds lines with drug doses and warning signs in the article and shows them as coloured cards, with a short summary at the top of the sheet. Works in the Light and Rich styles only. The detection is automatic, so always read the full text for decisions.': 'يجد الأسطر التي فيها جرعات الأدوية وعلامات التحذير في المقال ويعرضها كبطاقات ملونة مع ملخص قصير أعلى الورقة. يعمل في النمطين الخفيف والغني فقط. الكشف تلقائي، لذا اقرأ النص الكامل دائماً قبل أي قرار.',
  'If WikEM, Wikipedia and another course all have an article about the same condition, the sheet puts them together in one view with the source named on each part, instead of making you open each one.': 'إذا كان لدى WikEM وويكيبيديا ومقرر آخر مقال عن الحالة نفسها، تجمعها الورقة في عرض واحد مع ذكر المصدر عند كل جزء بدل أن تفتح كل مقال على حدة.',
  'Show captions': 'إظهار التعليقات',
  'Text under pictures and above tables.': 'النص أسفل الصور وأعلى الجداول.',
  'Shows the caption under each picture and above each table. Turn it off for a cleaner page when you only need the picture or the table.': 'يعرض التعليق أسفل كل صورة وأعلى كل جدول. أوقفه لصفحة أنظف عندما تحتاج الصورة أو الجدول فقط.',
  'Images & tables': 'الصور والجداول',
  'Pictures from the picture packs you installed.': 'صور من حزم الصور التي ثبّتها.',
  'Shows the pictures that come with your downloaded picture packs inside articles. Turn it off to read faster or save battery.': 'يعرض داخل المقالات الصور التي تأتي مع حزم الصور المنزّلة. أوقفه لقراءة أسرع أو لتوفير البطارية.',
  'Shows the tables of an article in the full article view. Wide tables scroll sideways and open full screen when you tap them.': 'يعرض جداول المقال في عرض المقال الكامل. الجداول العريضة تتحرك جانبياً وتُفتح بملء الشاشة عند الضغط عليها.',
  'When an article has no picture on the phone, the app can look for one on Wikipedia using only the article title. The picture is saved on the phone, so it works offline next time. Turn it off to stay fully offline.': 'عندما لا يكون للمقال صورة على الهاتف، يستطيع التطبيق البحث عن صورة في ويكيبيديا باستخدام عنوان المقال فقط. تُحفظ الصورة على الهاتف فتعمل دون إنترنت في المرة التالية. أوقفه لتبقى دون اتصال تماماً.',
  'Besides titles, the search also looks inside the article text. The first time it prepares an index on the phone, which takes a little while and some storage. Everything stays on the phone.': 'إلى جانب العناوين يبحث البحث داخل نص المقال أيضاً. في المرة الأولى يجهّز فهرساً على الهاتف يستغرق وقتاً قصيراً ومساحة تخزين. كل شيء يبقى على الهاتف.',
  'Puts short, structured sources at the top of the results, so you reach the practical summary before the long encyclopedia article.': 'يضع المصادر الموجزة المنظمة في أعلى النتائج لتصل إلى الملخص العملي قبل مقال الموسوعة الطويل.',
  'Suggest other search words': 'اقتراح كلمات بحث أخرى',
  'When a search finds little, the AI can suggest synonyms. Needs AI and internet.': 'عندما يجد البحث القليل يمكن للذكاء الاصطناعي اقتراح مرادفات. يحتاج إلى الذكاء الاصطناعي والإنترنت.',
  'If a search finds few results, the AI can suggest other words, such as the full name of an abbreviation. Only the short search words are sent, never your cases. It does nothing when AI is off or you are offline.': 'إذا وجد البحث نتائج قليلة يمكن للذكاء الاصطناعي اقتراح كلمات أخرى مثل الاسم الكامل لاختصار. تُرسل كلمات البحث القصيرة فقط وليس حالاتك أبداً. لا يفعل شيئاً عندما يكون الذكاء الاصطناعي متوقفاً أو لا يوجد إنترنت.',
  'Packs & downloads': 'الحزم والتنزيلات',
  'Protects your mobile data. With this on, the app asks before downloading picture packs or courses larger than 20 MB when you are not on Wi-Fi.': 'يحمي بيانات الجوال. عند تفعيله يسألك التطبيق قبل تنزيل حزم الصور أو المقررات الأكبر من 20 ميجابايت إن لم تكن على واي فاي.',
  'Storage used by each pack': 'المساحة التي تستخدمها كل حزمة',
  'Light: callout cards for doses and red flags.': 'خفيف: بطاقات تنبيه للجرعات وعلامات الخطر.',
  'Rich: cards, icons and highlighted key points.': 'غني: بطاقات وأيقونات ونقاط أساسية مظللة.',
  'Reading, study sheet, search, downloads, AI': 'القراءة وورقة المذاكرة والبحث والتنزيلات والذكاء الاصطناعي',
  'Raw text': 'النص الأصلي',
  'Formatted': 'منسق',
  'Copy as plain text': 'نسخ كنص عادي',
  'Copy as Markdown': 'نسخ بصيغة Markdown',
  'Copy table': 'نسخ الجدول',
  'No source': 'بلا مصدر',
  'What I could not verify': 'ما لم أستطع التحقق منه',
  'No sources given': 'لم تذكر مصادر',
  'Unverified parts': 'أجزاء غير مؤكدة',
  'Open link': 'فتح الرابط',
  'Copy link': 'نسخ الرابط',
  'Always verify with the original source and your local protocol.': 'تحقق دائما من المصدر الأصلي ومن البروتوكول المحلي.',
  '{n} red flags': '{n} علامات خطر',
  '{n} don\'t miss': '{n} تشخيصات لا تفوت',
  '{n} steps': '{n} خطوات',
  '{n} tables': '{n} جداول',
  '{n} sources': '{n} مصادر',
  'AI-generated, not medically reviewed. Verify with the cited source and your local protocol.': 'أنتجه الذكاء الاصطناعي ولم تتم مراجعته طبيا. تحقق من المصدر المذكور ومن البروتوكول المحلي.',
  'Overview': 'نظرة عامة',
  'Don\'t miss': 'لا تفوّت',
  'Key points': 'النقاط المهمة',
  'Steps': 'الخطوات',
  'Details': 'تفاصيل',
  '{n} red flag': 'علامة خطر واحدة',
  '{n} table': 'جدول واحد',
  '{n} source': 'مصدر واحد',
  'Ask AI is off': 'الذكاء الاصطناعي متوقف',
  'AI is optional. Turn it on and add your own key (Google Gemini has a free option) to ask any medical question, get deep-dives and see your library articles under each answer.': 'الذكاء الاصطناعي اختياري. فعّله وأضف مفتاحك الخاص (يوفّر Google Gemini خياراً مجانياً) لتسأل أي سؤال طبي وتحصل على شروحات معمّقة وترى مقالات مكتبتك تحت كل إجابة.',
  'MedLog keeps working fully without it: your cases, library and quizzes never need AI.': 'يعمل MedLog كاملاً من دونه: حالاتك ومكتبتك واختباراتك لا تحتاج إلى الذكاء الاصطناعي أبداً.',
  'Open Library & AI settings': 'افتح إعدادات المكتبة والذكاء الاصطناعي',
  'Ask AI': 'اسأل الذكاء الاصطناعي',
  'Earlier chats': 'المحادثات السابقة',
  'New chat': 'محادثة جديدة',
  'Ask anything medical. Answers are teaching notes that suggest, not orders. I add articles from your own library under each answer.': 'اسأل أي سؤال طبي. الإجابات ملاحظات تعليمية تقترح ولا تأمر. أضيف تحت كل إجابة مقالات من مكتبتك.',
  'Searching and writing the answer...': 'جارٍ البحث وكتابة الإجابة...',
  'Writing the answer...': 'جارٍ كتابة الإجابة...',
  'Web': 'الويب',
  'Ask a question...': 'اكتب سؤالاً...',
  'Saved as a note': 'تم الحفظ كملاحظة',
  'Saved in My files (Library)': 'تم الحفظ في «ملفاتي» (المكتبة)',
  'Could not save the file': 'تعذّر حفظ الملف',
  'Nothing to make cards from.': 'لا يوجد ما تُصنع منه بطاقات.',
  'Add up to {n} flashcards from this answer to your review deck?': 'إضافة حتى {n} بطاقة من هذه الإجابة إلى مجموعة المراجعة؟',
  '{n} flashcards added.': 'أُضيفت {n} بطاقة.',
  'No cited facts to make questions from. Ask with Web as the source to get cited answers.': 'لا توجد معلومات موثّقة بمصادر لصنع أسئلة منها. اسأل بمصدر «الويب» للحصول على إجابات موثّقة.',
  'Add up to {n} questions made from the cited facts to your AI question bank?': 'إضافة حتى {n} سؤالاً من المعلومات الموثّقة إلى بنك أسئلة الذكاء الاصطناعي؟',
  '{n} questions added.': 'أُضيف {n} سؤالاً.',
  'Source not opened': 'لم يُفتح المصدر',
  'This source has no usable https address.': 'لا يملك هذا المصدر عنوان https صالحاً.',
  'This address is not on your allowed list, so MedLog does not open it.': 'هذا العنوان ليس في قائمتك المسموحة، لذلك لا يفتحه MedLog.',
  'Copy address': 'نسخ العنوان',
  'Open in your browser?': 'فتح في المتصفح؟',
  '{h} is on your allowed list but is not shown inside MedLog. Open it in your phone browser?': 'الموقع {h} في قائمتك المسموحة لكنه لا يُعرض داخل MedLog. هل تفتحه في متصفح هاتفك؟',
  'AI suggestion: check before use. Not clinical advice.': 'اقتراح من الذكاء الاصطناعي: تحقق قبل الاستخدام. ليس نصيحة سريرية.',
  'Save as My file': 'حفظ في ملفاتي',
  'Make flashcards': 'صنع بطاقات',
  'Make quiz questions': 'صنع أسئلة اختبار',
  'Nothing was sent. Your library still works offline; these articles match your question:': 'لم يُرسل شيء. مكتبتك تعمل دون إنترنت؛ هذه المقالات تطابق سؤالك:',
  'Searched the web ({n} sources)': 'تم البحث في الويب ({n} مصادر)',
  'Answered from your library passages only.': 'الإجابة من مقاطع مكتبتك فقط.',
  'From model memory: may be outdated. Check the current guideline.': 'من ذاكرة النموذج: قد تكون قديمة. تحقق من الإرشاد الحالي.',
  'This provider has no live web search here. Answered from your library and the model: may be outdated.': 'هذا المزوّد لا يوفّر بحثاً مباشراً في الويب هنا. الإجابة من مكتبتك ومن النموذج: قد تكون قديمة.',
  'The live search quota is used up. Answered from your library and the model: may be outdated.': 'استُنفدت حصة البحث المباشر. الإجابة من مكتبتك ومن النموذج: قد تكون قديمة.',
  'Live search was refused for this key (not on its plan, or switched off by an admin). Answered from your library and the model: may be outdated.': 'رُفض البحث المباشر لهذا المفتاح (غير متاح في خطته أو أوقفه المشرف). الإجابة من مكتبتك ومن النموذج: قد تكون قديمة.',
  'Live search is switched off in the AI settings. Answered from your library and the model: may be outdated.': 'البحث المباشر متوقف في إعدادات الذكاء الاصطناعي. الإجابة من مكتبتك ومن النموذج: قد تكون قديمة.',
  'The model did not use web search for this answer, so it may be outdated. Check the current guideline.': 'لم يستخدم النموذج البحث في الويب لهذه الإجابة، لذا قد تكون قديمة. تحقق من الإرشاد الحالي.',
  'Address on your allowed list': 'العنوان في قائمتك المسموحة',
  'Allowed site, but the search did not return it: check the page': 'موقع مسموح لكن البحث لم يُرجعه: تحقق من الصفحة',
  'Not on your allowed list: not opened': 'ليس في قائمتك المسموحة: لم يُفتح',
  'No usable address': 'لا يوجد عنوان صالح',
  'Marked sources could not be verified against your allowed sites: check them before relying on them.': 'تعذّر التحقق من المصادر المعلّمة مقابل مواقعك المسموحة: راجعها قبل الاعتماد عليها.',
  'From your library': 'من مكتبتك',
  'No earlier chats yet.': 'لا توجد محادثات سابقة بعد.',
  'This article: {t}': 'هذا المقال: {t}',
  'This case': 'هذه الحالة',
  'Quiz question': 'سؤال اختبار',
  'Calculator: {t}': 'الحاسبة: {t}',
  'Library search: {t}': 'بحث في المكتبة: {t}',
  'Deep-dive': 'شرح معمّق',
  'Compare with...': 'قارن مع...',
  'Check against current guidelines': 'تحقق من الإرشادات الحالية',
  'Make questions': 'اصنع أسئلة',
  'Discuss (preview)': 'ناقش (معاينة)',
  'What would the senior ask?': 'ماذا سيسأل الاستشاري؟',
  'Explain': 'اشرح',
  'Which score?': 'أي مقياس؟',
  'Interpret': 'فسّر',
  'Deep-dive on this query': 'شرح معمّق لهذا البحث',
  'Today\'s brief': 'موجز اليوم',
  'Ask anything': 'اسأل أي شيء',
  'This case is marked "never send to AI".': 'هذه الحالة مُعلّمة «لا تُرسل إلى الذكاء الاصطناعي أبداً».',
  'No connection or AI is off.': 'لا يوجد اتصال أو أن الذكاء الاصطناعي متوقف.',
  'Cancelled: nothing was sent.': 'أُلغي: لم يُرسل شيء.',
  'Not found in your library. Switch the source to Web or Model to ask beyond your references.': 'غير موجود في مكتبتك. غيّر المصدر إلى «الويب» أو «النموذج» للسؤال خارج مراجعك.',
  'Hide until restart': 'إخفاء حتى إعادة التشغيل',
  'Hide in settings': 'إخفاء من الإعدادات',
  'You can turn the button on again in Library & AI settings.': 'يمكنك إعادة تشغيل الزر من إعدادات المكتبة والذكاء الاصطناعي.',
  'Library & AI settings': 'إعدادات المكتبة والذكاء الاصطناعي',
  'Daily AI limit reached ({n}). It resets tomorrow; you can raise it in the AI settings.': 'بلغتَ الحد اليومي للذكاء الاصطناعي ({n}). يُعاد ضبطه غداً، ويمكنك رفعه من إعدادات الذكاء الاصطناعي.',
  'Ask with web sources (Ask AI)': 'اسأل بمصادر من الويب (اسأل الذكاء الاصطناعي)',
  'Accredited sites and the latest guidelines': 'مواقع معتمدة وأحدث الإرشادات',
  'Only the articles you installed': 'فقط المقالات التي ثبّتَّها',
  'Model memory: may be outdated': 'ذاكرة النموذج: قد تكون قديمة',
  'Only your own list of sites': 'فقط قائمة مواقعك الخاصة',
  'AI is off. Turn it on in Settings to use this. The local tools below still work.': 'الذكاء الاصطناعي متوقف. فعّله من الإعدادات لاستخدام هذه الميزة. الأدوات المحلية أدناه تعمل بدونه.',
  'You are offline. Saved items and local tools still work.': 'أنت غير متصل بالإنترنت. العناصر المحفوظة والأدوات المحلية تعمل.',
  'The AI answer could not be used (it did not follow the format or had no valid sources). Nothing was saved. Try again.': 'تعذّر استخدام إجابة الذكاء الاصطناعي (لم تلتزم بالصيغة أو لم تحتوِ على مصادر صالحة). لم يُحفظ شيء. حاول مرة أخرى.',
  'No library passages found for this topic. Download a course in the Library, or switch the AI source to the web in Settings.': 'لم يتم العثور على مقاطع في المكتبة لهذا الموضوع. نزّل مقرراً من المكتبة أو غيّر مصدر الذكاء الاصطناعي إلى الويب من الإعدادات.',
  'This article has no text to check.': 'لا يحتوي هذا المقال على نص للتحقق منه.',
  'Choose a topic first.': 'اختر موضوعاً أولاً.',
  'The AI could not answer now. Try again later.': 'لم يستطع الذكاء الاصطناعي الإجابة الآن. حاول لاحقاً.',
  'Source: not stated (unverified)': 'المصدر: غير مذكور (غير موثّق)',
  'No saved questions yet. Generate some when AI is on and you are online.': 'لا توجد أسئلة محفوظة بعد. أنشئ بعضها عندما يكون الذكاء الاصطناعي مفعّلاً وأنت متصل.',
  '{a} new questions saved.': 'تم حفظ {a} أسئلة جديدة.',
  '{n} saved questions': '{n} سؤالاً محفوظاً',
  '{n} weak topics': '{n} مواضيع ضعيفة',
  'Practice now': 'تدرّب الآن',
  'Generate more': 'أنشئ المزيد',
  'AI study': 'الدراسة بالذكاء الاصطناعي',
  'You are offline. Saved questions, saved sessions and the self-viva work without internet.': 'أنت غير متصل. الأسئلة والجلسات المحفوظة والاختبار الذاتي الشفهي تعمل بدون إنترنت.',
  'Practise with an examiner': 'تدرّب مع ممتحِن',
  'Check and compare': 'تحقق وقارن',
  'AI only suggests. It never changes your records, and every statement shows its source.': 'الذكاء الاصطناعي يقترح فقط. لا يغيّر سجلاتك أبداً، وكل عبارة تعرض مصدرها.',
  'No weak spots yet. Self-tests, viva sessions and written answers add to this list.': 'لا توجد نقاط ضعف بعد. الاختبارات الذاتية وجلسات الفيفا والإجابات المكتوبة تضيف إلى هذه القائمة.',
  'The AI could not help now. Your local plan above is complete.': 'لم يستطع الذكاء الاصطناعي المساعدة الآن. خطتك المحلية أعلاه كاملة.',
  'Today’s plan': 'خطة اليوم',
  'Nothing urgent today. Open a Core 250 topic, take a self-test, or log a case.': 'لا شيء عاجل اليوم. افتح موضوعاً من الـ 250 الأساسية أو أجرِ اختباراً ذاتياً أو سجّل حالة.',
  'Built from your own data on this phone. Turn AI on in Settings for a short motivating note and a focused order.': 'مبنية من بياناتك على هذا الهاتف. فعّل الذكاء الاصطناعي من الإعدادات لملاحظة تحفيزية قصيرة وترتيب مركّز.',
  'Focus my 25 minutes with AI': 'ركّز دقائقي الـ 25 بالذكاء الاصطناعي',
  'Only counts leave the phone for the AI note: no topics, no case data.': 'يغادر الهاتف الأعداد فقط للملاحظة: لا مواضيع ولا بيانات حالات.',
  'For your rotation': 'لتدويرك الحالي',
  'Choose a specialty or type a topic.': 'اختر تخصصاً أو اكتب موضوعاً.',
  'Nothing to practise yet: take a self-test or download a course first.': 'لا شيء للتدرّب عليه بعد: أجرِ اختباراً ذاتياً أو نزّل مقرراً أولاً.',
  'Viva / OSCE examiner': 'ممتحِن الفيفا / OSCE',
  'Topic (optional), e.g. pneumonia': 'الموضوع (اختياري)، مثل الالتهاب الرئوي',
  'Start with the AI examiner': 'ابدأ مع الممتحِن الذكي',
  'Self-viva on my weak topics (no AI)': 'فيفا ذاتي على مواضيعي الضعيفة (بدون ذكاء اصطناعي)',
  'Saved sessions': 'الجلسات المحفوظة',
  'No sessions yet.': 'لا توجد جلسات بعد.',
  'Submit answer': 'أرسل الإجابة',
  'The marking checklist stays hidden until the end.': 'تبقى قائمة التصحيح مخفية حتى النهاية.',
  'Scored by a local keyword check (the AI was not available): treat it as a rough estimate.': 'التقييم بفحص محلي للكلمات المفتاحية (الذكاء الاصطناعي غير متاح): اعتبره تقديراً تقريبياً.',
  'What a senior would expect': 'ما يتوقعه الأخصائي الأقدم',
  'Weak areas (saved to your weak spots, with review cards)': 'مجالات الضعف (حُفظت في نقاط ضعفك مع بطاقات مراجعة)',
  'No weak area this time. Well done.': 'لا مجال ضعف هذه المرة. أحسنت.',
  'Checklist and what a senior would expect': 'قائمة التصحيح وما يتوقعه الأخصائي الأقدم',
  'Self-viva: no AI, from your own weak topics': 'فيفا ذاتي: بدون ذكاء اصطناعي، من مواضيعك الضعيفة',
  'Say it aloud: definition, key features, investigations, management, pitfalls.': 'قلها بصوت عالٍ: التعريف، السمات الرئيسية، الفحوصات، العلاج، المزالق.',
  'Show key points': 'أظهر النقاط الرئيسية',
  'Open the article to check yourself.': 'افتح المقال لتتحقق بنفسك.',
  'How did you do?': 'كيف كان أداؤك؟',
  'Saved session': 'جلسة محفوظة',
  'Teach me': 'علّمني',
  '{a} of {b} checks answered correctly': 'أجبت على {a} من {b} فحوصات بشكل صحيح',
  '{n} review cards added': 'أُضيفت {n} بطاقات مراجعة',
  'Make review cards from the checks': 'أنشئ بطاقات مراجعة من الأسئلة',
  'Step {i} of {n}': 'الخطوة {i} من {n}',
  'Check yourself': 'اختبر نفسك',
  'Show the expected answer': 'أظهر الإجابة المتوقعة',
  'I had it': 'كنت أعرفها',
  'Topic, e.g. atrial fibrillation': 'الموضوع، مثل الرجفان الأذيني',
  'From my weak spots': 'من نقاط ضعفي',
  'Ask me first': 'اسألني أولاً',
  'First, what do you already know?': 'أولاً، ماذا تعرف مسبقاً؟',
  'Pre-shift quiz': 'اختبار ما قبل المناوبة',
  'Quick questions for your rotation: {r}.': 'أسئلة سريعة لتدويرك: {r}.',
  '{n} questions ready': '{n} أسئلة جاهزة',
  'Some questions were just generated from your library.': 'أُنشئت بعض الأسئلة للتو من مكتبتك.',
  'No saved AI questions for this rotation yet.': 'لا توجد أسئلة ذكاء اصطناعي محفوظة لهذا التدوير بعد.',
  'Turn AI on and go online once to build some. Meanwhile the standard quiz works offline.': 'فعّل الذكاء الاصطناعي واتصل بالإنترنت مرة لإنشاء بعضها. في الأثناء يعمل الاختبار العادي دون إنترنت.',
  'Use the standard quiz (5 questions)': 'استخدم الاختبار العادي (5 أسئلة)',
  'Case of the day': 'حالة اليوم',
  'Read the topic of the day instead': 'اقرأ موضوع اليوم بدلاً من ذلك',
  'Show the answer and the teaching point': 'أظهر الإجابة والنقطة التعليمية',
  'Case finished. Come back tomorrow for a new one.': 'انتهت الحالة. عد غداً لحالة جديدة.',
  'Go through it again': 'راجعها مرة أخرى',
  'Another case': 'حالة أخرى',
  'Earlier cases': 'حالات سابقة',
  'Guideline check': 'فحص الإرشادات',
  'Article': 'المقال',
  'Recently read': 'قُرئت مؤخراً',
  'The live web search did not run for this check: treat the result as unverified.': 'لم يعمل البحث المباشر في الويب لهذا الفحص: اعتبر النتيجة غير موثّقة.',
  'AI suggestion: check before use. Your article was not changed.': 'اقتراح من الذكاء الاصطناعي: تحقق قبل الاستخدام. لم يتغير مقالك.',
  'Compare guidelines': 'قارن الإرشادات',
  'Topic, e.g. blood pressure targets': 'الموضوع، مثل أهداف ضغط الدم',
  'AI suggestion: check the guidelines themselves before acting.': 'اقتراح من الذكاء الاصطناعي: راجع الإرشادات نفسها قبل التصرف.',
  'Written answers': 'الإجابات المكتوبة',
  'Pick a saved question, write the answer in your own words (type or dictate) and the AI grades it against the cited source: strengths, missing points and wrong statements. Offline you get a keyword check.': 'اختر سؤالاً محفوظاً واكتب الإجابة بكلماتك (كتابةً أو إملاءً) ويقيّمها الذكاء الاصطناعي مقابل المصدر المذكور: نقاط القوة والنقاط الناقصة والعبارات الخاطئة. دون إنترنت تحصل على فحص للكلمات المفتاحية.',
  'No saved questions yet. Generate some in the AI question bank first.': 'لا توجد أسئلة محفوظة بعد. أنشئ بعضها في بنك أسئلة الذكاء الاصطناعي أولاً.',
  'Graded answers': 'الإجابات المقيَّمة',
  'Written answer': 'إجابة مكتوبة',
  'Strengths': 'نقاط القوة',
  'Missing points': 'نقاط ناقصة',
  'Wrong statements': 'عبارات خاطئة',
  'Saved on this phone. Wrong statements are only those you wrote that contradict the source.': 'حُفظت على هذا الهاتف. العبارات الخاطئة هي فقط ما كتبته وتعارض المصدر.',
  'Questions come from your library and cited answers. Saved questions work offline.': 'الأسئلة من مكتبتك ومن إجابات موثّقة بمصادر. الأسئلة المحفوظة تعمل دون إنترنت.',
  'You are offline: practise from your saved questions.': 'أنت غير متصل: تدرّب من أسئلتك المحفوظة.',
  'AI is off: you can still practise your saved questions. Turn AI on in Settings to generate more.': 'الذكاء الاصطناعي متوقف: يمكنك التدرّب على أسئلتك المحفوظة. فعّله من الإعدادات لإنشاء المزيد.',
  'AI is off. Everything here has a local version that works without AI: your plan, the self-viva, saved questions. Turn AI on in Settings for examiner, teaching and checks.': 'الذكاء الاصطناعي متوقف. لكل ما هنا نسخة محلية تعمل بدونه: خطتك والفيفا الذاتي والأسئلة المحفوظة. فعّله من الإعدادات للممتحِن والتعليم والفحوصات.',
  'Offline: the local plan above still works': 'دون إنترنت: الخطة المحلية أعلاه تعمل',
  '{n} card due': '{n} بطاقة مستحقة',
  '{n} cards due': '{n} بطاقات مستحقة',
  'A senior examiner (AI) presents a fictional case from your library or from guidelines, asks one question at a time and scores you against a hidden checklist. Typed or dictated answers.': 'ممتحِن أقدم (ذكاء اصطناعي) يعرض حالة خيالية من مكتبتك أو من الإرشادات، ويسأل سؤالاً واحداً في كل مرة ويقيّمك مقابل قائمة تصحيح مخفية. الإجابات كتابةً أو إملاءً.',
  'You are offline: you can review saved sessions or use the self-viva below.': 'أنت غير متصل: يمكنك مراجعة الجلسات المحفوظة أو استخدام الفيفا الذاتي أدناه.',
  'AI is off. You can review saved sessions and use the self-viva (your own weak topics, no AI).': 'الذكاء الاصطناعي متوقف. يمكنك مراجعة الجلسات المحفوظة واستخدام الفيفا الذاتي (مواضيعك الضعيفة، بدون ذكاء اصطناعي).',
  'Self-viva': 'فيفا ذاتي',
  'Finish and see the checklist': 'أنهِ واعرض قائمة التصحيح',
  'I missed it, finish': 'فاتتني، أنهِ',
  'I missed it, next': 'فاتتني، التالي',
  'You choose a topic. The AI first asks what you already know, then explains step by step and checks you. Every step shows its source.': 'تختار موضوعاً. يسألك الذكاء الاصطناعي أولاً عمّا تعرفه، ثم يشرح خطوة بخطوة ويختبرك. كل خطوة تعرض مصدرها.',
  'You are offline. Open the topic in the Library instead.': 'أنت غير متصل. افتح الموضوع في المكتبة بدلاً من ذلك.',
  'AI is off. Search the topic in the Library, or turn AI on in Settings.': 'الذكاء الاصطناعي متوقف. ابحث عن الموضوع في المكتبة أو فعّله من الإعدادات.',
  'No current rotation is set: the questions come from all your saved questions.': 'لا يوجد تدوير حالي: الأسئلة من كل أسئلتك المحفوظة.',
  'Next step': 'الخطوة التالية',
  'The AI looks up current guidelines on the allowed sites (Settings > AI > sources) and compares them with the article. Items without a source are marked "No source found": nothing is claimed without one.': 'يبحث الذكاء الاصطناعي عن الإرشادات الحالية في المواقع المسموحة (الإعدادات > الذكاء الاصطناعي > المصادر) ويقارنها بالمقال. العناصر بلا مصدر تُعلَّم «لم يُعثر على مصدر»: لا يُدّعى شيء دون مصدر.',
  'You are offline. Saved checks stay visible. A new check needs internet.': 'أنت غير متصل. تبقى الفحوصات المحفوظة ظاهرة. الفحص الجديد يحتاج إنترنت.',
  'AI is off. Saved checks stay visible. Turn AI on in Settings to check an article.': 'الذكاء الاصطناعي متوقف. تبقى الفحوصات المحفوظة ظاهرة. فعّله من الإعدادات لفحص مقال.',
  'Check now': 'افحص الآن',
  'No change found in the allowed sources. This does not prove that the article is up to date.': 'لم يُعثر على تغيير في المصادر المسموحة. هذا لا يثبت أن المقال محدّث.',
  'The AI finds the current guideline of each organisation on the allowed sites and lists where they differ. Differences are only listed when both sources were found.': 'يجد الذكاء الاصطناعي الإرشاد الحالي لكل منظمة في المواقع المسموحة ويعرض أين يختلفان. لا تُعرض الاختلافات إلا عند العثور على المصدرين معاً.',
  'You are offline: comparison needs internet.': 'أنت غير متصل: المقارنة تحتاج إنترنت.',
  'AI is off. Turn AI on in Settings to compare guidelines.': 'الذكاء الاصطناعي متوقف. فعّله من الإعدادات لمقارنة الإرشادات.',
  'Grade my answer': 'قيّم إجابتي',
  'Check my answer (local)': 'افحص إجابتي (محلياً)',
  'Microphone permission was denied. You can allow it in the phone settings, or type instead.': 'رُفض إذن الميكروفون. يمكنك السماح به من إعدادات الهاتف أو الكتابة بدلاً من ذلك.',
  'Nothing was heard. Try again, or type instead.': 'لم يُسمع شيء. حاول مرة أخرى أو اكتب بدلاً من ذلك.',
  'Voice input needs a language pack or internet on this phone. You can type instead.': 'يحتاج الإدخال الصوتي إلى حزمة لغة أو إنترنت على هذا الهاتف. يمكنك الكتابة بدلاً من ذلك.',
  'Voice input is not available right now. You can type instead.': 'الإدخال الصوتي غير متاح الآن. يمكنك الكتابة بدلاً من ذلك.',
  'Stop dictation': 'أوقف الإملاء',
  'Dictate with your voice': 'أملِ بصوتك',
  'Adapt this week': 'كيّف هذا الأسبوع',
  'Last 7 days: {d} of {p} planned items done.': 'آخر 7 أيام: أُنجز {d} من {p} عنصراً مخططاً.',
  'No answers in the last 7 days.': 'لا إجابات في آخر 7 أيام.',
  'Answers: {a}% correct ({n} questions).': 'الإجابات: {a}% صحيحة ({n} سؤالاً).',
  'No specialty needs more or less time this week. The plan will be re-spread from today over the days left.': 'لا يحتاج أي تخصص إلى وقت أكثر أو أقل هذا الأسبوع. ستُوزَّع الخطة من جديد من اليوم على الأيام المتبقية.',
  'Proposed changes': 'التغييرات المقترحة',
  '{a} to {b}': 'من {a} إلى {b}',
  'more time': 'وقت أكثر',
  'less time': 'وقت أقل',
  'You did less than half of the planned items, so the rest is re-spread over the days left.': 'أنجزت أقل من نصف العناصر المخططة، لذا يُعاد توزيع الباقي على الأيام المتبقية.',
  'Turn AI on in Settings for a short explanation of the changes.': 'فعّل الذكاء الاصطناعي من الإعدادات لشرح قصير للتغييرات.',
  'No explanation available now. The changes above are complete.': 'لا يتوفر شرح الآن. التغييرات أعلاه كاملة.',
  'More AI study tools': 'المزيد من أدوات الدراسة بالذكاء الاصطناعي',
  'Viva / OSCE, teach me, pre-shift quiz, case of the day, guideline check': 'فيفا / OSCE، علّمني، اختبار ما قبل المناوبة، حالة اليوم، فحص الإرشادات',
  'Cited fact': 'معلومة موثّقة بمصدر',
  'AI (web answer)': 'ذكاء اصطناعي (إجابة من الويب)',
  'Write my answer (AI grades)': 'اكتب إجابتي (يقيّمها الذكاء الاصطناعي)',
  'Review flashcards': 'راجع البطاقات',
  'Fix a weak spot': 'عالج نقطة ضعف',
  'Read it, then 5 questions': 'اقرأه ثم 5 أسئلة',
  'Revisit it in the library': 'راجعه في المكتبة',
  'From your exam plan': 'من خطة امتحانك',
  'New Core 250 topic': 'موضوع جديد من الـ 250 الأساسية',
  'Viva (oral exam)': 'فيفا (امتحان شفهي)',
  'OSCE: history': 'OSCE: أخذ القصة',
  'OSCE: examination': 'OSCE: الفحص السريري',
  'OSCE: data interpretation': 'OSCE: تفسير البيانات',
  'OSCE: management': 'OSCE: العلاج',
  'Short case': 'حالة قصيرة',
  'In my reference': 'في مرجعي',
  'Current guideline': 'الإرشاد الحالي',
  'Changed': 'تغيّر',
  'No change': 'لا تغيير',
  'No source found': 'لم يُعثر على مصدر',
  'Unclear': 'غير واضح',
  'Aspect': 'الجانب',
  'not addressed': 'غير مذكور',
  '{n} items may be out of date: check the guideline itself before changing anything.': 'قد يكون {n} عناصر قديمة: راجع الإرشاد نفسه قبل تغيير أي شيء.',
  '1 item may be out of date: check the guideline itself before changing anything.': 'قد يكون عنصر واحد قديماً: راجع الإرشاد نفسه قبل تغيير أي شيء.',
  'Checked on': 'تاريخ الفحص',
  'Talk through': 'تحدّث عن',
  'Fictional case · AI examiner': 'حالة خيالية · ممتحِن ذكي',
  'Fictional case': 'حالة خيالية',
  'Local keyword check only: it cannot tell if what you wrote is correct.': 'فحص محلي للكلمات المفتاحية فقط: لا يستطيع معرفة صحة ما كتبته.',
  'Offline: saved sessions': 'دون إنترنت: الجلسات المحفوظة',
  'Take a self-test': 'أجرِ اختباراً ذاتياً',
  'Mentions': 'يذكر',
  'Not mentioned': 'غير مذكور',
  'Cases built from guidelines, scored against a hidden checklist. Offline: saved sessions and self-viva.': 'حالات مبنية من الإرشادات وتُقيَّم مقابل قائمة مخفية. دون إنترنت: الجلسات المحفوظة والفيفا الذاتي.',
  'Teach me a topic': 'علّمني موضوعاً',
  'The AI asks first, then explains step by step with checks.': 'يسأل الذكاء الاصطناعي أولاً ثم يشرح خطوة بخطوة مع أسئلة تحقق.',
  '5 quick questions about your current rotation.': '5 أسئلة سريعة عن تدويرك الحالي.',
  'A fictional learning case from your library, discussed step by step.': 'حالة تعليمية خيالية من مكتبتك تُناقش خطوة بخطوة.',
  'Type an answer to a saved question and get graded against its source.': 'اكتب إجابة لسؤال محفوظ واحصل على تقييم مقابل مصدره.',
  'Is my reference still current? What changed?': 'هل ما زال مرجعي محدّثاً؟ ماذا تغيّر؟',
  'ESC vs AHA (or any two) for a topic, as a table.': 'ESC مقابل AHA (أو أي اثنتين) لموضوع ما، في جدول.',
  'Fictional case · {d}': 'حالة خيالية · {d}',
  'Start the AI examiner': 'ابدأ مع الممتحِن الذكي',
  'Questions for your rotation': 'أسئلة لتدويرك',
  '{n} cases today': '{n} حالات اليوم',
  '{n} unfinished drafts': '{n} مسودات غير مكتملة',
  '{n} flashcards due': '{n} بطاقات مراجعة مستحقة',
  'day {a} of {b}': 'اليوم {a} من {b}',
  'done': 'تم',
  'Paste a free-text note or dictate it with the microphone button. The note is cleaned and shown to you before anything is sent. Nothing is saved until you tap Apply.': 'الصق ملاحظة نصية حرة أو أملِها بزر الميكروفون. تُنظَّف الملاحظة وتُعرض عليك قبل إرسال أي شيء. لا يُحفظ شيء حتى تضغط تطبيق.',
  'What would the senior ask, examine and order next on this case? Use it to rehearse before the ward round.': 'ماذا سيسأل الأخصائي الأقدم، وماذا سيفحص، وماذا سيطلب بعد ذلك في هذه الحالة؟ استخدمه للتدرب قبل جولة الجناح.',
  'Prepare me for the senior': 'جهّزني للأخصائي الأقدم',
  'Link this case to the guidelines that cover its working diagnosis: organisation, year and the main recommendation. Only the diagnosis, age group, sex and setting are sent. This gives general recommendations, never orders for this patient.': 'اربط هذه الحالة بالإرشادات التي تغطي تشخيصها العامل: الجهة والسنة والتوصية الرئيسية. يُرسل فقط التشخيص والفئة العمرية والجنس ومكان الرعاية. يعطي توصيات عامة وليس أوامر لهذا المريض.',
  'Link this case to guidelines': 'اربط هذه الحالة بالإرشادات',
  'A plain-language explanation you could give to the patient or family. It is a draft: check it with your senior and say it in your own words.': 'شرح بلغة بسيطة يمكنك تقديمه للمريض أو أسرته. هو مسودة: راجعها مع الأخصائي الأقدم وقلها بكلماتك.',
  'Explain this to a patient': 'اشرح هذا لمريض',
  'DRAFT for you to check. Do not hand it to a patient as it is.': 'مسودة لتراجعها. لا تسلّمها لمريض كما هي.',
  'Teaching points and a 3-question mini quiz built from this case. You can save the cited questions to your AI bank and make review cards.': 'نقاط تعليمية واختبار قصير من 3 أسئلة مبني على هذه الحالة. يمكنك حفظ الأسئلة الموثقة في بنك الذكاء الاصطناعي وإنشاء بطاقات مراجعة.',
  'Teaching points and mini quiz': 'نقاط تعليمية واختبار قصير',
  'Senior': 'الأقدم',
  'Patient': 'المريض',
  'Teach': 'تعليم',
  'No new cited questions to save.': 'لا توجد أسئلة موثقة جديدة للحفظ.',
  '{n} questions saved to your AI bank.': 'تم حفظ {n} أسئلة في بنك الذكاء الاصطناعي.',
  'Mini quiz': 'اختبار قصير',
  'No source cited: not saved to the bank.': 'لا مصدر مذكور: لم يُحفظ في البنك.',
  'Save cited questions to AI bank': 'احفظ الأسئلة الموثقة في بنك الذكاء الاصطناعي',
  'No source was cited. Treat this as unverified and check a guideline.': 'لم يُذكر أي مصدر. اعتبر هذا غير موثق وراجع إرشادات.',
  'Procedure deep-dive': 'تعمّق في الإجراء',
  'Steps, complications and consent points for a procedure, with sources. For learning: always be supervised until you are signed off.': 'خطوات الإجراء ومضاعفاته ونقاط الموافقة، مع المصادر. للتعلم: كن دائمًا تحت الإشراف حتى يتم اعتمادك.',
  'Explain this procedure': 'اشرح هذا الإجراء',
  'Without AI: read about it in your library': 'بدون الذكاء الاصطناعي: اقرأ عنه في مكتبتك',
  'Which score fits this case?': 'أي مقياس يناسب هذه الحالة؟',
  'Describe the situation in your own words (no names), or pick one of your cases. The app calculates every number itself: the AI only suggests which score fits and where it comes from.': 'صف الحالة بكلماتك (دون أسماء)، أو اختر إحدى حالاتك. التطبيق يحسب كل رقم بنفسه: الذكاء الاصطناعي يقترح فقط أي مقياس يناسب ومصدره.',
  'Type a description': 'اكتب وصفًا',
  'Use one of my cases': 'استخدم إحدى حالاتي',
  'Clinical picture (no names or ids)': 'الصورة السريرية (دون أسماء أو أرقام هوية)',
  'e.g. 70 year old with cough, fever, confusion and low blood pressure': 'مثال: عمره 70 سنة مع سعال وحمى وتخليط وانخفاض ضغط الدم',
  'Only de-identified fields are sent, and you see them before sending.': 'تُرسل الحقول مجهولة الهوية فقط، وتراها قبل الإرسال.',
  'Which score fits?': 'أي مقياس يناسب؟',
  'Open calculator': 'افتح الحاسبة',
  'Interpret my result': 'فسّر نتيجتي',
  'Drug information from AI can be wrong or out of date. It is shown only when a named source supports it. Verify every drug, dose and interaction in your hospital formulary or national formulary before acting. This tool is never combined with a patient case.': 'قد تكون معلومات الدواء من الذكاء الاصطناعي خاطئة أو قديمة. لا تُعرض إلا عندما يدعمها مصدر مسمّى. تحقق من كل دواء وجرعة وتداخل في دستور أدوية مستشفاك أو الدستور الوطني قبل التصرف. لا تُدمج هذه الأداة مع حالة مريض أبدًا.',
  'No verified source found': 'لم يُعثر على مصدر موثق',
  'Please check your hospital formulary.': 'يرجى مراجعة دستور أدوية مستشفاك.',
  'The live web search did not run, so these links are not confirmed. Open each source and check it.': 'لم يعمل البحث المباشر على الويب، لذلك هذه الروابط غير مؤكدة. افتح كل مصدر وتحقق منه.',
  'Sources from your library': 'مصادر من مكتبتك',
  'Verify in your hospital formulary.': 'تحقق في دستور أدوية مستشفاك.',
  'Drug check': 'فحص الدواء',
  'Interactions': 'التداخلات',
  'Kidney dose adjustment': 'تعديل الجرعة في القصور الكلوي',
  'Liver dose adjustment': 'تعديل الجرعة في القصور الكبدي',
  'Pregnancy and breastfeeding': 'الحمل والرضاعة',
  'Children': 'الأطفال',
  'First drug': 'الدواء الأول',
  'Drug': 'الدواء',
  'Second drug': 'الدواء الثاني',
  'Extra detail (optional, no patient data)': 'تفصيل إضافي (اختياري، دون بيانات مريض)',
  'e.g. eGFR 30, third trimester': 'مثال: eGFR 30، الثلث الأخير',
  'Check with sources': 'افحص مع المصادر',
  'Sources come from the allowed list in AI settings (trusted web) or from your own library packs. Without a source there is no answer.': 'تأتي المصادر من القائمة المسموحة في إعدادات الذكاء الاصطناعي (الويب الموثوق) أو من حزم مكتبتك. بدون مصدر لا توجد إجابة.',
  'The source mode is set to the model only. Switch to trusted web or to your library in AI settings: drug questions are answered only with a source.': 'وضع المصدر مضبوط على النموذج فقط. بدّل إلى الويب الموثوق أو إلى مكتبتك في إعدادات الذكاء الاصطناعي: تُجاب أسئلة الدواء بمصدر فقط.',
  'Your installed library has no passage that covers this. Install a drug reference pack, or switch the source to trusted web in AI settings.': 'لا توجد في مكتبتك المثبتة فقرة تغطي هذا. ثبّت حزمة مرجع أدوية، أو بدّل المصدر إلى الويب الموثوق في إعدادات الذكاء الاصطناعي.',
  'Write the drug name (two names for an interaction).': 'اكتب اسم الدواء (اسمان للتداخل).',
  'The search found nothing from the trusted sources that answers this with a citation.': 'لم يجد البحث في المصادر الموثوقة ما يجيب عن هذا مع استشهاد.',
  'Tags added to {n} cases.': 'أُضيفت وسوم إلى {n} حالات.',
  'Suggest tags for untagged cases': 'اقترح وسومًا للحالات بلا وسوم',
  '{n} cases have no tags.': '{n} حالات بلا وسوم.',
  'The AI sees a short de-identified line per case (age group, sex, specialty, complaint, diagnosis). Cases marked "Never send this case to AI" are skipped. You see it before it is sent, and nothing is saved until you tap Apply.': 'يرى الذكاء الاصطناعي سطرًا قصيرًا مجهول الهوية لكل حالة (الفئة العمرية، الجنس، التخصص، الشكوى، التشخيص). تُتخطى الحالات المعلّمة "لا ترسل هذه الحالة إلى الذكاء الاصطناعي". تراه قبل الإرسال ولا يُحفظ شيء حتى تضغط تطبيق.',
  'Suggest tags ({n} cases)': 'اقترح وسومًا ({n} حالات)',
  'All your cases have tags.': 'كل حالاتك لديها وسوم.',
  'Apply selected': 'طبّق المحدد',
  'Morning brief': 'ملخص الصباح',
  'Write my brief': 'اكتب ملخصي',
  'AI helper': 'مساعد الذكاء الاصطناعي',
  'AI is off. MedLog works fully without it.': 'الذكاء الاصطناعي متوقف. يعمل MedLog بالكامل بدونه.',
  'This AI feature is switched off in AI settings.': 'هذه الميزة متوقفة في إعدادات الذكاء الاصطناعي.',
  'Needs internet. Saved answers can still be read.': 'يحتاج إنترنت. يمكن قراءة الإجابات المحفوظة.',
  'Turn on AI': 'شغّل الذكاء الاصطناعي',
  'Make practice questions from your library': 'أنشئ أسئلة تدريب من مكتبتك',
  '{n} questions saved': '{n} أسئلة محفوظة',
  'A short fictional teaching case on a topic from your weak spots or your main specialty': 'حالة تعليمية خيالية قصيرة في موضوع من نقاط ضعفك أو تخصصك الرئيسي',
  'Make today\'s case': 'أنشئ حالة اليوم',
  'Ask AI about this query': 'اسأل الذكاء الاصطناعي عن هذا البحث',
  'AI portfolio tools': 'أدوات الملف الشخصي بالذكاء الاصطناعي',
  'AI is off': 'الذكاء الاصطناعي متوقف',
  'Reflection draft': 'مسودة تأمل',
  'Goal gap analysis': 'تحليل فجوة الأهداف',
  'CV summary': 'ملخص السيرة الذاتية',
  'Pick one of your own cases and get a first draft of a reflection to start from. It is a DRAFT: you edit it and write it in your own words before it counts as your reflection.': 'اختر إحدى حالاتك واحصل على مسودة أولى لتأمل تبدأ منها. هي مسودة: تعدّلها وتكتبها بكلماتك قبل أن تُعدّ تأملك.',
  'Draft my reflection': 'اكتب مسودة تأملي',
  'DRAFT written by AI. Edit it and make it yours before you rely on it.': 'مسودة كتبها الذكاء الاصطناعي. عدّلها واجعلها لك قبل أن تعتمد عليها.',
  'Edit and save as my reflection': 'عدّل واحفظ كتأمل لي',
  'Your goals against the days left, calculated on your phone. The AI only suggests next actions from these numbers.': 'أهدافك مقابل الأيام المتبقية، محسوبة على هاتفك. يقترح الذكاء الاصطناعي إجراءات تالية من هذه الأرقام فقط.',
  'Suggest next actions': 'اقترح إجراءات تالية',
  'Suggestions from your own numbers. You decide what to do.': 'اقتراحات من أرقامك أنت. أنت تقرر ماذا تفعل.',
  'Add targets to your current rotation to see the gaps.': 'أضف أهدافًا لدورتك الحالية لترى الفجوات.',
  '{n} to go': 'متبقي {n}',
  'A summary paragraph for your CV, written from the counts of your logbook (no case content). Edit it before you use it.': 'فقرة ملخص لسيرتك الذاتية، مكتوبة من أعداد سجلك (دون محتوى الحالات). عدّلها قبل استخدامها.',
  'Everything': 'كل شيء',
  'Nothing logged yet.': 'لم يُسجَّل شيء بعد.',
  'Write CV text': 'اكتب نص السيرة الذاتية',
  'DRAFT written by AI from your counts. Check every number and edit it.': 'مسودة كتبها الذكاء الاصطناعي من أعدادك. تحقق من كل رقم وعدّلها.',
  'Suggest tags': 'اقترح وسومًا',
  'All logged work': 'كل العمل المسجّل',
  'AI is off. Turn on AI': 'الذكاء الاصطناعي متوقف. شغّله',
  'Suggest tags for my untagged cases': 'اقترح وسومًا لحالاتي بلا وسوم',
  'AI tools': 'أدوات الذكاء الاصطناعي',
  'AI-generated, not medically reviewed (saved answer)': 'مولّد بالذكاء الاصطناعي، لم يُراجع طبيًا (إجابة محفوظة)',
  'What is the Ask AI button?': 'ما هو زر اسأل الذكاء الاصطناعي؟',
  'When AI is on, a floating Ask AI button appears on the main screens. It knows which screen you are on (case, calculator, quiz, library, home, search) and offers the right actions. Drag it where you like; switch it off, or per screen, in Settings, AI assistant.': 'عند تشغيل الذكاء الاصطناعي يظهر زر عائم "اسأل الذكاء الاصطناعي" على الشاشات الرئيسية. يعرف أي شاشة تفتح (حالة، حاسبة، اختبار، مكتبة، رئيسية، بحث) ويعرض الإجراءات المناسبة. اسحبه حيث تشاء؛ وأوقفه، أو لكل شاشة، من الإعدادات، مساعد الذكاء الاصطناعي.',
  'What sources does the AI use?': 'ما المصادر التي يستخدمها الذكاء الاصطناعي؟',
  'In Settings, AI assistant, choose the sources: trusted web (live search limited to guideline sites that you can edit), your own library, the model only, or your own list of sites. Web answers name the organisation, the year and the link. When no source is found the answer says so.': 'في الإعدادات، مساعد الذكاء الاصطناعي، اختر المصادر: الويب الموثوق (بحث مباشر محصور بمواقع الإرشادات التي يمكنك تعديلها)، أو مكتبتك، أو النموذج فقط، أو قائمة مواقعك. تذكر إجابات الويب الجهة والسنة والرابط. وعند عدم وجود مصدر تقول الإجابة ذلك.',
  'Which language does the AI answer in?': 'بأي لغة يجيب الذكاء الاصطناعي؟',
  'English by default. In Settings, AI assistant you can choose an Arabic explanation with English medical terms, or Arabic. Clinical terms, drug names and guideline names stay in English.': 'الإنجليزية افتراضيًا. في الإعدادات، مساعد الذكاء الاصطناعي يمكنك اختيار شرح بالعربية مع مصطلحات طبية إنجليزية، أو العربية. تبقى المصطلحات السريرية وأسماء الأدوية والإرشادات بالإنجليزية.',
  'How are AI answers formatted?': 'كيف تُنسَّق إجابات الذكاء الاصطناعي؟',
  'Answers come as a structured sheet with sections (overview, differential, investigations, management, red flags, guidelines) and source chips; tap a chip to open the source. You can switch to plain text, hide citations, copy the answer or report a problem.': 'تأتي الإجابات كورقة منظمة بأقسام (نظرة عامة، تشخيص تفريقي، فحوصات، تدبير، علامات خطر، إرشادات) ورقائق مصادر؛ اضغط رقاقة لفتح المصدر. يمكنك التبديل إلى نص عادي، أو إخفاء الاستشهادات، أو نسخ الإجابة، أو الإبلاغ عن مشكلة.',
  'What is the AI question bank?': 'ما هو بنك أسئلة الذكاء الاصطناعي؟',
  'Home, AI question bank keeps practice questions made from your library or from cited answers. Saved questions work offline. From a case, the Teach tab saves cited questions and review cards.': 'الرئيسية، بنك أسئلة الذكاء الاصطناعي يحفظ أسئلة تدريب مصنوعة من مكتبتك أو من إجابات موثقة. تعمل الأسئلة المحفوظة دون إنترنت. ومن الحالة يحفظ تبويب تعليم الأسئلة الموثقة وبطاقات المراجعة.',
  'Can the AI test me like a viva or OSCE?': 'هل يمكن للذكاء الاصطناعي أن يختبرني كالفيفا أو الأوسكي؟',
  'Yes. In Ask AI choose viva practice: the AI asks one question at a time and gives feedback. In a case, Socratic mode does the same with your own case.': 'نعم. في اسأل الذكاء الاصطناعي اختر تدريب الفيفا: يسأل سؤالًا واحدًا في كل مرة ويعطي تغذية راجعة. وفي الحالة يفعل الوضع السقراطي الشيء نفسه مع حالتك.',
  'How do I check a topic against the current guidelines?': 'كيف أفحص موضوعًا مقابل الإرشادات الحالية؟',
  'In Ask AI use the guideline check action, or open the Guidelines tab of a case: you get a table of organisation, year and recommendation for the working diagnosis. It never gives orders for your patient.': 'في اسأل الذكاء الاصطناعي استخدم إجراء فحص الإرشادات، أو افتح تبويب الإرشادات في الحالة: تحصل على جدول بالجهة والسنة والتوصية للتشخيص العامل. لا يعطي أوامر لمريضك أبدًا.',
  'Can I dictate notes by voice?': 'هل يمكنني إملاء الملاحظات بالصوت؟',
  'Yes. The microphone button next to a note or answer field uses the speech recogniser of your phone. In the case assistant, the Fields tab turns a dictated or pasted note into suggested fields that you apply or undo.': 'نعم. زر الميكروفون بجانب حقل الملاحظة أو الإجابة يستخدم التعرف على الكلام في هاتفك. وفي مساعد الحالة يحوّل تبويب الحقول ملاحظة مُملاة أو ملصقة إلى حقول مقترحة تطبقها أو تتراجع عنها.',
  'How does Drug check work?': 'كيف يعمل فحص الدواء؟',
  'Calculators, Drug check answers questions on interactions, kidney or liver dose, pregnancy and children only when it finds a cited source on the allowed sites or in your library packs. Otherwise it says No verified source found. Always verify in your hospital formulary.': 'الحاسبات، فحص الدواء يجيب عن أسئلة التداخلات وجرعة الكلى أو الكبد والحمل والأطفال فقط عندما يجد مصدرًا موثقًا في المواقع المسموحة أو في حزم مكتبتك. وإلا يقول لم يُعثر على مصدر موثق. تحقق دائمًا في دستور أدوية مستشفاك.',
  'How do I find the right score for a case?': 'كيف أجد المقياس المناسب لحالة؟',
  'Calculators, Which score fits this case? suggests scores with their sources. The app does all the arithmetic, and Interpret my result explains your number with guideline thresholds.': 'الحاسبات، أي مقياس يناسب هذه الحالة؟ يقترح مقاييس مع مصادرها. يقوم التطبيق بكل العمليات الحسابية، وتشرح فسّر نتيجتي رقمك بحدود الإرشادات.',
  'What is the morning brief?': 'ما هو ملخص الصباح؟',
  'On Home it lists today cases, due flashcards, goals, rotation and weak topics, all computed on your phone. With AI on it can write a short paragraph from those counts only.': 'في الرئيسية يعرض حالات اليوم والبطاقات المستحقة والأهداف والدورة ومواضيع الضعف، كلها محسوبة على هاتفك. ومع تشغيل الذكاء الاصطناعي يمكنه كتابة فقرة قصيرة من هذه الأعداد فقط.',
  'What can AI do in my portfolio?': 'ماذا يفعل الذكاء الاصطناعي في ملفي؟',
  'Portfolio, AI portfolio tools: a reflection draft from one of your cases (marked DRAFT), a goal gap analysis with next actions, and a CV summary from your counts. Reports can add a marked AI paragraph.': 'الملف، أدوات الذكاء الاصطناعي: مسودة تأمل من إحدى حالاتك (معلّمة كمسودة)، وتحليل فجوة الأهداف مع إجراءات تالية، وملخص سيرة ذاتية من أعدادك. ويمكن للتقارير إضافة فقرة معلّمة من الذكاء الاصطناعي.',
  'Where are the AI settings?': 'أين إعدادات الذكاء الاصطناعي؟',
  'Settings, AI assistant: provider and key, sources and allowed sites, answer language and length, formatting, the floating button, which features are on, the daily limit and the activity log.': 'الإعدادات، مساعد الذكاء الاصطناعي: المزود والمفتاح، والمواقع المسموحة، ولغة الإجابة وطولها، والتنسيق، والزر العائم، والميزات المفعّلة، والحد اليومي، وسجل النشاط.',
  'What is the access approval?': 'ما هي موافقة الوصول؟',
  'If your administrator turned on access control, the app shows a request code that you send to the administrator, who returns an approval code. Settings, Access shows the status and the days left. It is checked offline and no patient data is involved.': 'إذا فعّل المسؤول التحكم بالوصول يعرض التطبيق رمز طلب ترسله إلى المسؤول فيعيد لك رمز موافقة. تعرض الإعدادات، الوصول الحالة والأيام المتبقية. يُتحقق منه دون إنترنت ولا تتدخل بيانات مرضى.',
  'What if I do not use AI?': 'ماذا لو لم أستخدم الذكاء الاصطناعي؟',
  'Everything in MedLog works without it. Each AI action stays visible but greyed with a Turn on AI link, and nothing is sent anywhere until you turn AI on and confirm.': 'كل شيء في MedLog يعمل بدونه. يبقى كل إجراء ذكاء اصطناعي ظاهرًا لكنه رمادي مع رابط شغّل الذكاء الاصطناعي، ولا يُرسل شيء إلى أي مكان حتى تشغّله وتؤكد.',
  'left': 'متبقٍ',
  'Could not save': 'تعذّر الحفظ',
  'What is': 'ما هو',
  'Selected dates': 'تواريخ محددة',
  'colour color palette': 'لون ألوان لوحة الألوان',
