  'Contacting the AI...': 'جارٍ الاتصال بالذكاء الاصطناعي...',
  'Taking longer than usual. Live web search is slow on a weak connection. You can cancel and try again without it.': 'يستغرق وقتًا أطول من المعتاد. البحث الحي في الويب بطيء على اتصال ضعيف. يمكنك الإلغاء والمحاولة بدونه.',
  'Taking longer than usual. Check your connection, or cancel and try again.': 'يستغرق وقتًا أطول من المعتاد. تحقّق من اتصالك أو ألغِ وحاول مجددًا.',
  'Trying again without web search.': 'نحاول مجددًا بدون البحث في الويب.',
  'Cancelled.': 'أُلغي الطلب.',
  'The AI took too long to answer. Check your connection, then try again.': 'استغرق الذكاء الاصطناعي وقتًا طويلًا. تحقّق من اتصالك ثم حاول مجددًا.',
  'Connection check': 'فحص الاتصال',
  'Copy report': 'نسخ التقرير',
