  'Paste a key to check it too.': 'ألصق مفتاحًا لفحصه أيضًا.',
  'Unticked items count as absent.': 'العناصر غير المعلَّمة تُحسب غير موجودة.',
  'Answer every question to see the result.': 'أجب عن كل الأسئلة لتظهر النتيجة.',
  'Rule positive': 'القاعدة إيجابية',
  'Rule negative': 'القاعدة سلبية',
  'Presentation cards': 'بطاقات الأعراض والعلامات',
  'Ask, examine, red flags, first steps': 'ماذا تسأل وتفحص، العلامات الحمراء، أولى الخطوات',
  'Rotation hub': 'مركز التدوير',
  'Topics, procedures and targets for your rotation': 'مواضيع وإجراءات وأهداف تدويرك',
  'Where to find the current ones': 'أين تجد الحالية منها',
  'Search a presentation': 'ابحث عن عرض مرضي',
  'Drafted from public clinical guidance. No drug doses are given. Always check your hospital protocol and a senior.': 'صيغت من إرشادات سريرية عامة. لا تتضمن جرعات أدوية. راجع دائمًا بروتوكول مستشفاك وطبيبًا أقدم.',
  'Can\'t miss': 'لا يجوز تفويتها',
  'Must ask': 'يجب أن تسأل',
  'Must examine': 'يجب أن تفحص',
  'Most likely': 'الأرجح',
  'First investigations': 'الفحوص الأولى',
  'First actions': 'الإجراءات الأولى',
  'Related calculators': 'حاسبات مرتبطة',
  'Search the library for this': 'ابحث عن هذا في المكتبة',
  'Cases you logged here': 'حالات سجلتها هنا',
  'Core topics studied': 'المواضيع الأساسية التي درستها',
  'Core topics': 'المواضيع الأساسية',
  'Must know': 'يجب معرفته',
  'Common presentations': 'الأعراض الشائعة',
  'Suggested case targets': 'أعداد حالات مقترحة',
  'A suggestion, not your program\'s official numbers': 'اقتراح وليس الأعداد الرسمية لبرنامجك',
  'Topic lists come from public curricula and were drafted with an AI assistant. Check them against your own program.': 'قوائم المواضيع مأخوذة من مناهج عامة وصيغت بمساعدة الذكاء الاصطناعي. قارنها بمنهج برنامجك.',
  'Search guidelines': 'ابحث في الإرشادات',
  'Links open in your browser. Guideline versions change: check the year and the status before you rely on one.': 'تُفتح الروابط في متصفحك. تتغير نسخ الإرشادات: تحقق من السنة والحالة قبل الاعتماد على أي منها.',
  'Privacy policy': 'سياسة الخصوصية',
  'What stays on this phone and what is sent when you use optional features': 'ما يبقى على هذا الهاتف وما يُرسل عند استخدام الميزات الاختيارية',
  'Contact': 'التواصل',
  'Save this history as my template': 'احفظ هذا التاريخ المرضي كقالب لي',
  'Name this template': 'سمِّ هذا القالب',
  'Template name': 'اسم القالب',
  'Write something in the history first.': 'اكتب شيئًا في التاريخ المرضي أولًا.',
  'Template saved. Long-press it to delete.': 'حُفظ القالب. اضغط مطولًا عليه لحذفه.',
  'Delete this template?': 'حذف هذا القالب؟',
  'Same patient and outcome': 'المريض نفسه والنتيجة',
  '{n} linked cases': '{n} حالات مرتبطة',
  'How did this case end?': 'كيف انتهت هذه الحالة؟',
  'Cases of the same patient': 'حالات المريض نفسه',
  'Linking joins cases without any name or number, so you can follow one patient over time.': 'الربط يجمع الحالات دون أي اسم أو رقم، لتتابع مريضًا واحدًا عبر الزمن.',
  'Improved': 'تحسّن',
  'Worse': 'ساء',
  'Died': 'توفي',
  'Lost to follow-up': 'انقطعت المتابعة',
  'Link another case': 'اربط حالة أخرى',
  'Add a follow-up case': 'أضف حالة متابعة',
  'Remove the link': 'أزل الربط',
  'Remove the link?': 'إزالة الربط؟',
  'This case stays; it is only separated from the other cases of the same patient.': 'تبقى هذه الحالة، وتنفصل فقط عن الحالات الأخرى للمريض نفسه.',
  'Linked. No name or number is stored: only a shared hidden group.': 'تم الربط. لا يُخزَّن أي اسم أو رقم: فقط مجموعة مخفية مشتركة.',
  'Problem list (free text)': 'قائمة المشاكل (نص حر)',
  '{a} active, {r} resolved': '{a} نشطة، {r} محلولة',
  'One line per problem. Tick it when it is resolved.': 'سطر لكل مشكلة. علّمها عند حلّها.',
  'Import the lines from the text below': 'استورد الأسطر من النص أدناه',
  'Nothing new to import.': 'لا جديد لاستيراده.',
  '{n} problems imported.': 'استُوردت {n} مشاكل.',
  'New problem': 'مشكلة جديدة',
  'Problem': 'مشكلة',
  'Since': 'منذ',
  'Lab results and trends': 'نتائج المختبر واتجاهاتها',
  '{n} tests': '{n} فحوص',
  'Add numbers (for example Hb, creatinine, CRP) on different days to see how they move.': 'أضف أرقامًا (مثل Hb وcreatinine وCRP) في أيام مختلفة لترى كيف تتغير.',
  'Arrows compare the last result with the one before. They are not normal or abnormal flags.': 'تقارن الأسهم آخر نتيجة بالتي قبلها. وليست علامات طبيعي أو غير طبيعي.',
  'Add a result': 'أضف نتيجة',
  'Value': 'القيمة',
  'Unit (as your lab reports it)': 'الوحدة (كما يذكرها مختبرك)',
  'No results left.': 'لا نتائج متبقية.',
  'Error log': 'سجل الأخطاء',
  'Unexpected errors are kept here on this phone only. Nothing is sent anywhere. Copy the log if you want to report a problem.': 'تُحفظ الأخطاء غير المتوقعة هنا على هذا الهاتف فقط. لا يُرسل شيء إلى أي جهة. انسخ السجل إن أردت الإبلاغ عن مشكلة.',
  'Unexpected errors kept on this phone, to copy when reporting a problem': 'أخطاء غير متوقعة محفوظة على هذا الهاتف لتنسخها عند الإبلاغ عن مشكلة',
  'Copy log': 'انسخ السجل',
  'No errors recorded.': 'لا أخطاء مسجلة.',
  'Copied.': 'تم النسخ.',
  'AI quality check': 'فحص جودة الذكاء الاصطناعي',
  'Sends fixed medical test questions (no patient data) to your own AI key and checks whether the answers contain the key facts and avoid unsafe statements. Use it to compare models. A pass is a keyword match, not a clinical judgement.': 'يرسل أسئلة طبية ثابتة (بلا بيانات مرضى) إلى مفتاحك الخاص ويتحقق من احتواء الإجابات على الحقائق الأساسية وخلوّها من العبارات غير الآمنة. استخدمه للمقارنة بين النماذج. النجاح هنا مطابقة كلمات وليس حكمًا سريريًا.',
  'Run the check': 'شغّل الفحص',
  'Passed': 'ناجحة',
  'Safety traps': 'أسئلة فخ السلامة',
  'All 60': 'كل الـ60',
  '{n} questions': '{n} سؤالًا',
  'No answer': 'لا إجابة',
  '{n} requests failed (connection or key). They are not counted.': 'فشل {n} طلبات (اتصال أو مفتاح). لا تُحتسب.',
  'Stop': 'إيقاف',
  'Add the trusted-source map': 'أضف خريطة المصادر الموثوقة',
  'The map is already in your list.': 'الخريطة موجودة في قائمتك أصلًا.',
  '{n} sites added.': 'أُضيفت {n} مواقع.',
  'Lets you see unusual errors': 'يتيح لك رؤية الأخطاء غير المعتادة',
  'How do I use Presentation cards?': 'كيف أستخدم بطاقات الأعراض والعلامات؟',
  'In the Library tab open Presentation cards, search a symptom such as chest pain, and read what to ask, what to examine, the red flags, the can\'t-miss diagnoses and the first steps. They hold no drug doses. Check your hospital protocol.': 'في تبويب المكتبة افتح بطاقات الأعراض والعلامات وابحث عن عرض مثل ألم الصدر، واقرأ ماذا تسأل وتفحص والعلامات الحمراء والتشخيصات التي لا يجوز تفويتها وأولى الخطوات. لا تتضمن جرعات أدوية. راجع بروتوكول مستشفاك.',
  'What is the Rotation hub?': 'ما هو مركز التدوير؟',
  'In the Library tab open Rotation hub, pick a specialty and see its core topics (tick them as you study), common presentations, red flags, procedures and suggested case numbers. The search button next to a topic looks it up in your library.': 'في تبويب المكتبة افتح مركز التدوير واختر تخصصًا لترى مواضيعه الأساسية (علّمها أثناء دراستك) والأعراض الشائعة والعلامات الحمراء والإجراءات وأعداد الحالات المقترحة. زر البحث بجانب كل موضوع يبحث عنه في مكتبتك.',
  'Which clinical scores are in Calculators?': 'ما المقاييس السريرية الموجودة في الحاسبات؟',
  'Calculators now include many more scores, for example SOFA, qSOFA, HEART, TIMI, NIHSS, ABCD2, Alvarado, Child-Pugh, MELD, PHQ-9, GAD-7, Apgar, Padua, HAS-BLED, Glasgow-Blatchford, Bishop, Ottawa rules and the Canadian CT head rule. Answer every question to see the result. Each score shows its source and limits.': 'تتضمن الحاسبات الآن مقاييس أكثر بكثير، مثل SOFA وqSOFA وHEART وTIMI وNIHSS وABCD2 وAlvarado وChild-Pugh وMELD وPHQ-9 وGAD-7 وApgar وPadua وHAS-BLED وGlasgow-Blatchford وBishop وقواعد Ottawa وقاعدة Canadian CT head. أجب عن كل الأسئلة لتظهر النتيجة. يعرض كل مقياس مصدره وحدوده.',
  'How do I follow one patient over time?': 'كيف أتابع مريضًا واحدًا عبر الزمن؟',
  'In the Info tab of a case open Same patient and outcome. Link another case of the same patient or add a follow-up case. No name or number is stored: the cases only share a hidden group. Set the outcome of the case there too.': 'في تبويب المعلومات في الحالة افتح المريض نفسه والنتيجة. اربط حالة أخرى لنفس المريض أو أضف حالة متابعة. لا يُخزَّن اسم ولا رقم: تشترك الحالات في مجموعة مخفية فقط. وحدّد هناك أيضًا نتيجة الحالة.',
  'How do I track lab results and problems?': 'كيف أتتبع نتائج المختبر والمشاكل؟',
  'In the Investigations tab add numeric results (for example Hb or creatinine) on different days to see the trend. In the Assessment tab use the Problem list and tick problems when resolved. You can import the lines you already wrote.': 'في تبويب الفحوص أضف نتائج رقمية (مثل Hb أو creatinine) في أيام مختلفة لترى الاتجاه. وفي تبويب التقييم استخدم قائمة المشاكل وعلّم المشكلة عند حلّها. يمكنك استيراد الأسطر التي كتبتها سابقًا.',
  'What is the error log?': 'ما هو سجل الأخطاء؟',
  'Settings, Data & recovery, Error log keeps the last unexpected errors on this phone only. Copy it when you report a problem. Nothing is sent anywhere.': 'يحتفظ سجل الأخطاء (الإعدادات ثم البيانات والاستعادة) بآخر الأخطاء غير المتوقعة على هذا الهاتف فقط. انسخه عند الإبلاغ عن مشكلة. لا يُرسل شيء إلى أي جهة.',
  'What is the AI quality check?': 'ما هو فحص جودة الذكاء الاصطناعي؟',
  'In AI settings, AI quality check sends fixed medical test questions with no patient data to your own AI key and reports how many answers contained the key facts and avoided unsafe statements. Use it to compare models. It is a keyword check, not a clinical judgement.': 'في إعدادات الذكاء الاصطناعي يرسل فحص الجودة أسئلة طبية ثابتة بلا بيانات مرضى إلى مفتاحك الخاص ويبيّن كم إجابة احتوت الحقائق الأساسية وتجنبت العبارات غير الآمنة. استخدمه للمقارنة بين النماذج. هو فحص كلمات وليس حكمًا سريريًا.',
  'Results (oldest to newest)': 'النتائج (من الأقدم إلى الأحدث)',
