  'Import the dosing files you prepared from your books or hospital protocols. They stay on this phone and work offline.': 'استورد ملفات الجرعات التي جهّزتها من كتبك أو بروتوكولات مستشفاك. تبقى على هذا الهاتف وتعمل بدون إنترنت.',
