  'File format': 'صيغة الملف',
  'Dosing file format': 'صيغة ملف الجرعات',
  'A JSON file with schemaVersion 1, meta (id, title, source), drugs (name, aka, class, routes, regimens with indication, population, route, dose, frequency, duration, max, notes, page; renal, hepatic, pregnancy, cautions, contraindications, interactions, monitoring, adverse, pearls) and durations (condition, regimen, duration, notes, page). Several files or a ZIP can be imported. The files stay on this phone.': 'ملف JSON فيه schemaVersion بقيمة 1، وmeta (id وtitle وsource)، وdrugs (الاسم والأسماء التجارية والصنف والطرق والـregimens بالاستطباب والفئة والجرعة والتكرار والمدة والحد الأقصى والملاحظات والصفحة؛ والكلى والكبد والحمل والاحتياطات وموانع الاستعمال والتداخلات والمراقبة والأعراض الجانبية)، وdurations (الحالة والعلاج والمدة والملاحظات والصفحة). يمكن استيراد عدة ملفات أو ملف ZIP. تبقى الملفات على هذا الهاتف.',
